const path = require('path');
require('dotenv').config({ path: path.resolve(__dirname, '..', '.env') });
const mongoose = require('mongoose');

const SCHOOL_ID = new mongoose.Types.ObjectId('69ce960a98ca4ee738d25416');
const CREATED_BY = new mongoose.Types.ObjectId('69ce960b98ca4ee738d25432');

let blockNum = 0;
function bid() { return 'block-' + String(++blockNum).padStart(3, '0'); }

function t(order, content) {
  return { blockId: bid(), type: 'text', order, content, points: 0, hints: [], explanation: '', metadata: {}, curriculumNodeId: null, cognitiveLevel: null };
}
function q(order, question, options, correctIndex, explanation, hints) {
  return {
    blockId: bid(), type: 'quiz', order,
    content: JSON.stringify({ question, options, correctIndex }),
    points: 1, hints: hints || [], explanation: explanation || '',
    metadata: { options, correctIndex }, curriculumNodeId: null, cognitiveLevel: null,
  };
}
function fb(order, text, blanks, explanation, hints) {
  return {
    blockId: bid(), type: 'fill_blank', order,
    content: JSON.stringify({ text, blanks }),
    points: blanks.length, hints: hints || [], explanation: explanation || '',
    metadata: { blanks }, curriculumNodeId: null, cognitiveLevel: null,
  };
}

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 1: Positive Self-Concept and Self-Image (Term 1, Weeks 1–3)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch1_lesson1 = [
  t(1, '## Positive Self-Concept and Self-Image\n\nAs a Grade 7 learner, you are growing and changing in many ways. One of the most important things you can do is understand who you are and learn to feel good about yourself. This is your self-concept.\n\n### What Is Self-Concept?\n\nSelf-concept is the way you see yourself. It includes what you think about:\n\n- **Your body** — how you feel about the way you look\n- **Your abilities** — what you believe you can and cannot do\n- **Your personality** — the kind of person you think you are (shy, funny, kind, brave)\n- **Your relationships** — how you believe others see you\n\nEveryone has a self-concept. It can be positive (you feel good about yourself) or negative (you feel bad about yourself). The good news is that self-concept is not fixed — you can change it.'),
  t(2, '### Concept: Self-Image\n\nSelf-image is closely linked to self-concept. It is the picture you have of yourself in your mind.\n\n| Positive self-image | Negative self-image |\n|--------------------|-----------------|\n| "I am a good friend" | "Nobody really likes me" |\n| "I can learn if I try" | "I am too stupid to learn" |\n| "I look okay" | "I look ugly" |\n| "I matter" | "I do not matter" |\n\n**What shapes your self-image?**\n- The words people say to you (encouragement vs criticism)\n- Your past successes and failures\n- How you compare yourself to others\n- Messages from media (TV, social media, advertisements)\n\n**Basic hygiene and self-image:**\nLooking after your body is one of the simplest ways to feel better about yourself. Basic hygiene means:\n- Bathing or showering every day\n- Wearing clean clothes\n- Brushing your teeth twice a day\n- Keeping your hair neat and clean\n- Using deodorant as your body changes during puberty'),
  q(3, 'Thandi often tells herself, "I am not smart enough" and "Nobody likes me." What does this show about her self-image?',
    ['She has a negative self-image because she thinks badly about herself and her abilities', 'She has a positive self-image because she is honest', 'She has no self-image at all', 'She has a perfect self-image'], 0,
    'When a person constantly says negative things about themselves, it shows they have a negative self-image. Thandi needs to recognise her strengths and practise positive self-talk to improve how she sees herself.'),
  t(4, '### Positive Personal Qualities: Relationships with Self, Family, and Friends\n\nEveryone has positive qualities — things that make them special and valuable.\n\n**Identifying your positive qualities:**\nMake a list of things you are good at, even small things:\n- Are you a good listener?\n- Do you help at home without being asked?\n- Are you kind to younger children?\n- Can you make people laugh?\n- Are you good at a sport or creative activity?\n\n**Building positive relationships:**\n\n| Relationship | How to strengthen it |\n|-------------|--------------------|\n| **With yourself** | Accept who you are, forgive your mistakes, talk kindly to yourself |\n| **With family** | Help with chores, show respect, share your feelings, spend time together |\n| **With friends** | Be loyal, keep promises, listen, stand up for them, be honest |\n\n**Strategies to enhance self-image — respect for self:**\n- Focus on your strengths, not only your weaknesses\n- Set small goals and celebrate when you reach them\n- Stop comparing yourself to others — you are unique\n- Spend time with people who build you up, not tear you down\n- Try new activities to discover hidden talents'),
  fb(5, 'The way you see yourself is called your ___. Looking after your body through bathing, brushing teeth, and wearing clean clothes is called basic ___.',
    ['self-concept', 'hygiene'],
    'Self-concept is the overall picture you have of who you are. Basic hygiene keeps you healthy and helps you feel confident about yourself.'),
  t(6, '### Personal Interests, Abilities, and Potential\n\nEvery person has unique interests and abilities. Discovering yours is an important part of growing up.\n\n**Interests** are things you enjoy doing — reading, sport, drawing, cooking, building things, singing.\n\n**Abilities** are things you are good at — they can be physical, academic, creative, or social.\n\n**Potential** is what you COULD become if you develop your abilities through practice and hard work.\n\n**How to discover your interests and abilities:**\n- Try different activities — join a club, learn a new skill\n- Pay attention to what you enjoy — what makes time fly?\n- Ask people who know you — what do they think you are good at?\n- Reflect on past successes — what were you doing when you felt proud?\n\n**Strategies to enhance others\' self-image through positive actions:**\n- Give genuine compliments — "You did really well in that test!"\n- Include everyone — do not leave people out\n- Stand up for someone being bullied\n- Encourage a friend who is struggling\n- Respect differences — celebrate what makes each person unique'),
  q(7, 'Sipho is not good at sport but loves drawing and can sketch detailed pictures of animals. His friends sometimes tease him for not playing soccer. What should Sipho do?',
    ['Recognise that drawing is a valuable ability and continue developing it — everyone has different strengths', 'Give up drawing and force himself to play soccer', 'Stop being friends with everyone', 'Believe he has no talents at all'], 0,
    'Every person has unique abilities. Sipho\'s talent for drawing is a real strength that could lead to a career in art, design, or architecture. He should not give up his talent just because it is different from what his friends enjoy.'),
  t(8, '### Respect for Others and Diversity\n\nSouth Africa is a diverse country with people of many different cultures, languages, religions, and backgrounds. Respecting diversity means:\n\n- Treating everyone with dignity, even if they are different from you\n- Not making fun of someone\'s language, culture, religion, or appearance\n- Including people who are different from you in your group\n- Learning about other cultures and traditions\n- Standing up against discrimination, racism, and xenophobia\n\n**Respect for diversity in practice:**\n\n| Situation | Respectful response |\n|-----------|-------------------|\n| A new learner speaks a different language | Help them feel welcome, learn a greeting in their language |\n| Someone practises a different religion | Ask respectful questions, do not mock their beliefs |\n| A classmate has a disability | Include them in activities, treat them as equal |\n| A learner dresses differently due to culture | Appreciate the diversity, do not make fun of them |\n\n**Ubuntu:** The African philosophy of ubuntu means "I am because we are." It reminds us that we are all connected and that treating others well is treating ourselves well.'),
  q(9, 'A new learner joins your class from another province. She speaks Tshivenda and struggles with English. What is the BEST way to respond?',
    ['Welcome her, help her when she does not understand, and try to learn a few words in Tshivenda', 'Ignore her because she cannot speak your language', 'Laugh at the way she speaks', 'Tell her she should not be at your school'], 0,
    'The ubuntu philosophy teaches us to welcome and support others. Helping the new learner and showing interest in her language builds a positive, inclusive school environment and reflects the spirit of diversity.'),
  fb(10, 'The African philosophy that means "I am because we are" is called ___. Treating everyone with dignity regardless of their differences is called respecting ___.',
    ['ubuntu', 'diversity'],
    'Ubuntu is a core African value that reminds us of our shared humanity. Respecting diversity means valuing and including people from all backgrounds.'),
];

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 2: Puberty and Emotional Changes (Term 1, Weeks 4–6)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch2_lesson1 = [
  t(1, '## Changes During Puberty\n\nPuberty is the time when your body changes from a child\'s body into an adult\'s body. It usually begins between ages 9 and 14 and can last several years. Both boys and girls go through puberty, but the changes are different.\n\n### Changes in Boys and Girls: Puberty and Gender Constructs\n\n**Physical changes in girls:**\n- Breasts begin to develop\n- Hips become wider\n- Body hair grows (underarms, legs, pubic area)\n- Menstruation (periods) begins\n- Skin may become oily, leading to pimples\n- Growth spurt — you grow taller quickly\n\n**Physical changes in boys:**\n- Voice deepens (breaks or "cracks")\n- Facial hair begins to grow\n- Shoulders become broader\n- Body hair grows (underarms, chest, pubic area)\n- Growth spurt\n- Skin may become oily, leading to pimples\n- Wet dreams may occur\n\n**Changes in both boys and girls:**\n- Increased sweating and body odour\n- Mood swings and strong emotions\n- Growing interest in romantic relationships\n- Greater need for privacy and independence'),
  t(2, '### Physical and Emotional Changes\n\nPuberty is not just about physical changes — your emotions change too.\n\n**Emotional changes during puberty:**\n\n| Emotion | What it feels like |\n|---------|------------------|\n| **Mood swings** | Feeling happy one moment and sad or angry the next |\n| **Self-consciousness** | Worrying about how you look and what others think |\n| **Embarrassment** | Feeling awkward about body changes |\n| **Irritability** | Getting annoyed easily over small things |\n| **Sensitivity** | Feeling hurt more easily by comments or criticism |\n| **New attractions** | Developing crushes or romantic feelings |\n\n**Why these changes happen:**\nDuring puberty, your body produces hormones — chemical messengers that cause physical and emotional changes. These hormones are responsible for mood swings, new feelings, and body changes.\n\n**Managing emotional changes:**\n- Talk to a trusted adult (parent, teacher, or school counsellor) about what you are feeling\n- Keep a journal to express your emotions\n- Exercise regularly — it releases chemicals that improve your mood\n- Get enough sleep — teenagers need 8 to 10 hours per night\n- Be patient with yourself — everyone goes through this'),
  q(3, 'Bongani is 12 years old and has noticed his voice sometimes "cracks" when he speaks. His friends laugh at him. What should Bongani understand?',
    ['His voice is breaking because of puberty — this is completely normal and will settle over time', 'Something is wrong with his throat', 'He should stop talking until his voice is normal', 'Only he is going through this change'], 0,
    'Voice breaking is a normal part of puberty in boys. The larynx (voice box) is growing, causing the voice to crack or squeak temporarily. All boys experience this, and the voice settles into a deeper tone over time.'),
  t(4, '### Understanding the Changes and How They Impact Relationships\n\nThe changes during puberty affect how you relate to other people:\n\n**Impact on family relationships:**\n- You may want more privacy and independence\n- You might feel annoyed by parents\' rules\n- You may argue more with siblings\n- This is normal, but respect for family remains important\n\n**Impact on friendships:**\n- Friends become more important\n- You may change friend groups as interests change\n- Gossip, jealousy, and competition can cause problems\n- True friends support each other through difficult changes\n\n**Impact on romantic interest:**\n- Developing crushes is normal during puberty\n- At Grade 7 level, romantic relationships should be age-appropriate\n- Pressure to have a boyfriend or girlfriend is NOT okay\n- Focus on building healthy friendships first\n\n**Respect for your own and others\' body changes:**\n- Do not make fun of someone\'s body (breast size, height, weight, pimples)\n- Everyone develops at their own pace — early or late development is normal\n- Your body is your own — nobody has the right to touch you without your consent\n- Respect others\' privacy, especially in changing rooms'),
  fb(5, 'The chemical messengers that cause physical and emotional changes during puberty are called ___. During puberty, teenagers need ___ to 10 hours of sleep per night.',
    ['hormones', '8'],
    'Hormones are chemicals produced by the body that trigger the physical and emotional changes of puberty. Adequate sleep (8–10 hours) is essential for teenagers\' growth and emotional well-being.'),
  t(6, '### Appreciation and Acceptance of the Self and Others\n\nOne of the hardest parts of puberty is accepting how your body is changing. Some learners develop early, others develop late, and both can feel uncomfortable.\n\n**Accepting your changing body:**\n- Remember that everyone goes through puberty at their own pace\n- Early developers may feel self-conscious about standing out\n- Late developers may feel left behind, but their time will come\n- Your worth is not determined by how your body looks\n\n**Dealing with body image pressure:**\n- Social media shows filtered, edited images — real life is different\n- Celebrities and influencers do not look like their photos in real life\n- A healthy body is more important than a "perfect" body\n- Focus on what your body can DO, not just how it looks\n\n**Hygiene during puberty:**\nAs your body changes, hygiene becomes even more important:\n- Shower or bathe daily — increased sweating means stronger body odour\n- Use deodorant or antiperspirant\n- Wash your face to help prevent pimples\n- Girls: learn about menstrual hygiene (pads, menstrual cups)\n- Boys: understand wet dreams are normal and nothing to be ashamed of\n- Change underwear daily'),
  q(7, 'Zanele started her period at age 10, while most of her friends have not started yet. She feels embarrassed and different. What should she know?',
    ['Starting puberty early is completely normal — everyone develops at their own pace', 'Something is wrong with her body', 'She should not tell anyone', 'She should stop attending school until her friends catch up'], 0,
    'Girls can start menstruating anywhere between ages 9 and 16. Starting early or late is normal. Zanele should talk to a trusted adult about managing her period and know that her friends will go through the same experience later.'),
  t(8, '### Caring for Yourself During Puberty\n\nPuberty is a time to learn to take extra care of yourself:\n\n**Physical care:**\n- Eat healthy foods — your body needs nutrition to grow properly\n- Drink plenty of water\n- Exercise regularly — at least 60 minutes of physical activity per day\n- Get enough sleep (8–10 hours)\n- Practice good hygiene daily\n\n**Emotional care:**\n- Talk about your feelings — do not bottle them up\n- Spend time with positive friends\n- Take breaks from social media if it makes you feel bad about yourself\n- Do activities you enjoy — sport, music, art, reading\n- Ask for help when you need it — this is a sign of strength, not weakness\n\n**Where to get help:**\n- Parents or guardians\n- Teachers or school counsellors\n- Childline: 0800 055 555 (free, confidential)\n- A trusted older sibling, aunt, uncle, or grandparent\n- School nurse or clinic'),
  q(9, 'Which of the following is a healthy way to deal with the emotional changes of puberty?',
    ['Talk to a trusted adult about how you are feeling and exercise regularly', 'Keep all your feelings to yourself and never tell anyone', 'Spend more time on social media comparing yourself to others', 'Get angry and take it out on your family'], 0,
    'Talking to a trusted adult and exercising are two of the healthiest ways to cope with the emotional changes of puberty. Keeping feelings bottled up or comparing yourself on social media can make things worse.'),
  fb(10, 'Puberty usually begins between ages ___ and 14. During puberty, learners should get at least ___ minutes of physical activity per day.',
    ['9', '60'],
    'Puberty typically starts between ages 9 and 14, though the timing varies for each person. The World Health Organisation recommends at least 60 minutes of moderate physical activity daily for young people.'),
];

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 3: Peer Pressure and Coping Skills (Term 1, Weeks 7–9)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch3_lesson1 = [
  t(1, '## Peer Pressure: Effects and Coping Skills\n\nPeer pressure is when friends or classmates influence you to think, act, or behave in a certain way. As a Grade 7 learner, peer pressure becomes stronger because fitting in with your friends feels very important.\n\n### What Is Peer Pressure?\n\nPeer pressure can be:\n- **Direct** — someone tells you to do something ("Come on, just try it!")\n- **Indirect** — you feel pressure to copy what others are doing, even if no one asks you directly\n- **Positive** — peers encourage you to do good things (study harder, join a sport)\n- **Negative** — peers push you to do harmful things (bunk school, try substances, bully others)\n\n### How Peer Pressure May Influence an Individual\n\nPeer pressure can lead young people into dangerous situations:\n\n| Area | Negative peer pressure examples |\n|------|-------------------------------|\n| **Substance use** | Trying cigarettes, alcohol, dagga, or drugs because friends do it |\n| **Crime** | Shoplifting, vandalism, or gang involvement |\n| **Unhealthy sexual behaviour** | Engaging in sexual activity before being ready |\n| **Bullying** | Joining in when others bully someone to avoid being bullied yourself |\n| **Rebellious behaviour** | Breaking school rules, disrespecting teachers, or defying parents |'),
  t(2, '### The Dangers of Giving In to Negative Peer Pressure\n\nGiving in to negative peer pressure can have serious consequences:\n\n**Substance use:**\n- Experimenting with alcohol, cigarettes, or drugs can quickly lead to addiction\n- Substances damage the developing brain\n- Substance use leads to poor decisions, accidents, and health problems\n\n**Crime:**\n- Stealing, vandalism, or fighting can lead to a criminal record\n- A criminal record can ruin future job opportunities and education\n- Crime often leads to violence and injury\n\n**Unhealthy sexual behaviour:**\n- Teenage pregnancy can change your life forever\n- Sexually transmitted infections (STIs) including HIV\n- Emotional harm from relationships you are not ready for\n\n**Bullying:**\n- Causes serious emotional and physical harm to the victim\n- Bullies often end up in trouble with the law\n- Cyberbullying (online bullying) can be especially cruel because it reaches everywhere\n\n**Rebellious behaviour:**\n- Suspension or expulsion from school\n- Damaged relationships with parents and teachers\n- Missing out on education and opportunities'),
  q(3, 'Lebo\'s friends dare him to shoplift a chocolate bar from the local shop. What is this an example of?',
    ['Direct negative peer pressure — his friends are specifically telling him to commit a crime', 'Positive peer pressure — his friends are helping him', 'Indirect peer pressure — nobody is telling him directly', 'No peer pressure — it is his own idea'], 0,
    'This is direct negative peer pressure because Lebo\'s friends are specifically daring him to do something harmful and illegal. Shoplifting is a crime that can result in a criminal record.'),
  t(4, '### Appropriate Responses to Pressure: Assertiveness and Coping Skills\n\nYou have the right to say NO. Assertiveness means standing up for yourself in a calm, confident way.\n\n**Assertiveness skills:**\n\n| Technique | How to use it |\n|-----------|-------------|\n| **Say NO clearly** | "No, I do not want to do that" — do not mumble or hesitate |\n| **Give a reason** | "No thanks, I need to study" or "No, I do not drink" |\n| **Suggest an alternative** | "Let\'s play soccer instead" or "Let\'s go to the library" |\n| **Walk away** | If they keep pushing, simply leave — you do not owe anyone an explanation |\n| **Use the broken record** | Repeat your answer calmly: "No." "I said no." "My answer is still no." |\n| **Use humour** | Sometimes a joke can defuse the situation without conflict |\n| **Blame an authority** | "My parents will ground me" or "The teacher will catch us" |\n\n**The difference between assertive, aggressive, and passive:**\n\n| Style | What it looks like | Result |\n|-------|-------------------|--------|\n| **Assertive** | "No, I do not want to. Let\'s do something else." | You stand up for yourself respectfully |\n| **Aggressive** | "Get lost! You are stupid for doing that!" | You push others away and create conflict |\n| **Passive** | Saying nothing and going along with it | You give in and may get hurt |'),
  fb(5, 'Standing up for yourself in a calm and confident way is called being ___. Repeating your refusal calmly over and over is called the ___ record technique.',
    ['assertive', 'broken'],
    'Assertiveness means expressing yourself clearly and confidently without being aggressive. The broken record technique involves repeating your refusal calmly until the other person stops pressuring you.'),
  t(6, '### Negotiation Skills: The Ability to Disagree in Constructive Ways\n\nSometimes you do not need to say a flat "no" — you can negotiate:\n\n**Negotiation means finding a solution that works for everyone.**\n\n**Steps for constructive disagreement:**\n1. **Stay calm** — do not raise your voice or get emotional\n2. **Listen** — let the other person explain their point of view\n3. **Express your view** — use "I" statements: "I feel uncomfortable with this"\n4. **Look for a compromise** — "What if we do this instead?"\n5. **Agree or walk away** — if you cannot find a compromise, it is okay to walk away\n\n**Examples of constructive disagreement:**\n\n| Situation | Constructive response |\n|-----------|---------------------|\n| Friends want to watch a movie you do not like | "I would rather watch something else. Can we take turns choosing?" |\n| Someone insults your culture | "That is not true and it hurts. Please stop." |\n| A friend wants to copy your homework | "I worked hard on this. I can help you understand it, but I will not let you copy." |\n\n**Remember:** Disagreeing does not mean being rude. You can stand your ground AND keep your friendships.'),
  q(7, 'Nomsa\'s friend asks to copy her homework. Nomsa says, "I worked hard on this and it would not be fair. But I can explain the questions to you." What skill is Nomsa using?',
    ['Negotiation — she is offering a compromise while standing up for her values', 'Aggression — she is being mean', 'Passive behaviour — she is giving in', 'Bullying — she is making her friend feel bad'], 0,
    'Nomsa is negotiating by standing up for her values (not cheating) while offering a helpful alternative (explaining the questions). This is a mature, constructive approach that respects both herself and her friend.'),
  t(8, '### Where to Find Help\n\nIf peer pressure is causing you to feel unsafe, stressed, or unhappy, you can get help.\n\n**People who can help:**\n- A parent, guardian, or trusted family member\n- A teacher or school counsellor\n- A religious leader (pastor, imam, priest)\n- An older sibling or cousin you trust\n\n**Helplines (free and confidential):**\n\n| Organisation | Number | What they help with |\n|-------------|--------|--------------------|\n| **Childline** | 0800 055 555 | Any problem a child or teenager faces |\n| **Lifeline** | 0861 322 322 | Crisis counselling and support |\n| **SADAG** | 0800 567 567 | Depression, anxiety, and mental health |\n| **Stop Gender Violence** | 0800 150 150 | Gender-based violence |\n| **SAPS Emergency** | 10111 | Crime and safety emergencies |\n\n**Remember:**\n- Asking for help is brave, not weak\n- You are not alone — many learners deal with peer pressure\n- A trusted adult can help you find solutions you might not see on your own\n- If you are being bullied, ALWAYS tell an adult — it is not "snitching," it is protecting yourself'),
  q(9, 'Karabo is being cyberbullied — classmates are posting nasty comments about him on social media. He feels embarrassed to tell anyone. What should he do?',
    ['Tell a trusted adult (parent, teacher, or counsellor) and save screenshots as evidence — cyberbullying is serious', 'Respond with nastier comments to get revenge', 'Delete all his social media accounts and say nothing', 'Accept it because everyone gets bullied sometimes'], 0,
    'Cyberbullying is a serious form of bullying that can cause deep emotional harm. Karabo should tell a trusted adult immediately and keep evidence (screenshots). Adults can intervene, and cyberbullying can be reported to the school and even to the police.'),
  fb(10, 'The free Childline helpline number for children and teenagers in South Africa is ___. Cyberbullying means bullying that happens ___.',
    ['0800 055 555', 'online'],
    'Childline (0800 055 555) is a free, confidential helpline available 24 hours a day for children and teenagers in need. Cyberbullying takes place online through social media, messaging apps, and other digital platforms.'),
];

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 4: Study Skills and the World of Work (Term 1, Weeks 10–11)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch4_lesson1 = [
  t(1, '## Study Skills Basics\n\nDoing well at school opens doors to opportunities in the future. Learning how to study effectively is a skill that can be developed — it is not something you are born with.\n\n### The Importance of Reading and Studying\n\nReading and studying are the most important skills for success at school:\n\n**Why reading matters:**\n- Reading improves your vocabulary and language skills\n- Good readers perform better in ALL subjects, not just languages\n- Reading develops your imagination and critical thinking\n- Reading exposes you to new ideas and different perspectives\n\n**Why studying matters:**\n- Understanding a topic deeply helps you remember it longer\n- Good study habits reduce stress before tests and exams\n- Studying builds discipline and responsibility\n- Strong academic results create more choices for your future\n\n**The difference between reading and studying:**\n\n| Reading | Studying |\n|---------|--------|\n| Reading through your notes or textbook | Actively engaging with the material |\n| Can be passive — your eyes move but your brain drifts | Active — you think, question, summarise, and test yourself |\n| Not enough on its own to prepare for a test | Combines reading with understanding and practice |'),
  t(2, '### Reading for Enjoyment and Understanding\n\nThere are two main types of reading:\n\n**Reading for enjoyment:**\n- Read books, magazines, or articles about topics you love\n- Choose material in any language — reading in your home language is just as valuable\n- Make reading a daily habit — even 15 minutes a day makes a difference\n- Join the school library and borrow books regularly\n\n**Reading with understanding:**\nTo truly understand what you read, use these strategies:\n\n| Strategy | How to use it |\n|----------|-------------|\n| **Preview** | Look at headings, pictures, and key words before reading |\n| **Question** | Ask yourself: "What is this about? What do I already know?" |\n| **Read actively** | Underline or highlight key points; write notes in the margin |\n| **Summarise** | After each section, write the main idea in your own words |\n| **Review** | Go back over your notes and summaries to check understanding |\n\n**SQ3R method:**\n- **S**urvey — scan the text quickly\n- **Q**uestion — ask questions about what you expect to learn\n- **R**ead — read carefully for answers\n- **R**ecite — say the answers in your own words\n- **R**eview — check your answers against the text'),
  q(3, 'Lerato reads her notes five times before a test but still forgets everything. What is she probably doing wrong?',
    ['She is reading passively — she needs to use active study methods like summarising, questioning, and testing herself', 'She is reading too many times', 'She should read her notes only once', 'She should stop studying altogether'], 0,
    'Passive reading (just moving your eyes over the text) does not create strong memories. Active studying — summarising, asking questions, testing yourself, and teaching others — forces the brain to process information more deeply.'),
  t(4, '### Skills to Develop Memory: Ability to Recall\n\nMemory is like a muscle — the more you exercise it, the stronger it gets.\n\n**Memory techniques for Grade 7 learners:**\n\n| Technique | How it works | Example |\n|-----------|-------------|--------|\n| **Repetition** | Repeat information several times, spacing it out over days | Review your notes today, tomorrow, and again in three days |\n| **Mnemonics** | Create a word, sentence, or rhyme to remember facts | "My Very Educated Mother Just Served Us Noodles" (planets) |\n| **Chunking** | Break large amounts of information into smaller groups | Remember a phone number as 082-555-1234 instead of 0825551234 |\n| **Visualisation** | Create a picture in your mind to represent information | Imagine a story or scene related to what you are learning |\n| **Association** | Link new information to something you already know | "Photosynthesis — \'photo\' means light, so it is about plants using light" |\n| **Teaching** | Explain what you learned to someone else | Teach your sibling or friend the topic — if you can explain it, you know it |\n\n**Tips for better memory:**\n- Study in a quiet place with no distractions (no phone, no TV)\n- Take short breaks every 30–40 minutes\n- Drink water and eat brain-healthy foods (fruits, nuts, eggs)\n- Get enough sleep — your brain stores memories while you sleep'),
  fb(5, 'The SQ3R reading method stands for Survey, Question, Read, Recite, and ___. Creating a word or sentence to remember facts is called a ___.',
    ['Review', 'mnemonic'],
    'The SQ3R method is a structured approach to reading for understanding. A mnemonic is a memory aid — a word, sentence, or rhyme that helps you remember facts or lists.'),
  t(6, '### Creating a Study Routine\n\nA study routine helps you manage your time and stay on top of your schoolwork:\n\n**Steps to create a study routine:**\n1. Find a quiet, well-lit study space\n2. Study at the same time every day — routine builds habit\n3. Start with your hardest subject while your brain is fresh\n4. Take a 5–10 minute break after every 30–40 minutes\n5. Use active study methods — do not just read passively\n6. Put your phone away — it is the biggest distraction\n\n**Sample daily study plan for a Grade 7 learner:**\n\n| Time | Activity |\n|------|----------|\n| 14:30–15:00 | Arrive home, snack, relax |\n| 15:00–15:40 | Subject 1 (hardest subject first) |\n| 15:40–15:50 | Break |\n| 15:50–16:30 | Subject 2 |\n| 16:30–16:40 | Break |\n| 16:40–17:10 | Homework and revision |\n| 17:10 onwards | Free time, sport, family time |\n\n**Remember:** Quality is more important than quantity. Thirty focused minutes are better than two hours of distracted study with your phone buzzing every few minutes.'),
  q(7, 'Why should you study your hardest subject FIRST in your study routine?',
    ['Because your brain is freshest at the start, so you can focus better on difficult material', 'Because hard subjects take less time', 'Because it does not matter what order you study', 'Because easy subjects should be saved for the end as a reward'], 0,
    'Your brain has the most energy and concentration at the start of a study session. Tackling the hardest subject first means you give your best effort to the material that needs it most.'),
  t(8, '### Exam and Test Preparation\n\nPreparing for tests and exams requires planning:\n\n**Before the test:**\n- Start studying at least one week before — do not leave it for the night before\n- Make a study plan showing which topics to cover each day\n- Use past test papers to practise — they show you what to expect\n- Ask your teacher if you do not understand something\n- Study with a friend — quiz each other on the material\n\n**During the test:**\n- Read every question carefully before answering\n- Start with questions you know — build confidence first\n- Watch your time — do not spend too long on one question\n- Check your answers if you have time left\n- Write neatly — the marker must be able to read your work\n\n**After the test:**\n- Look at your marked test to learn from your mistakes\n- Ask your teacher to explain questions you got wrong\n- Do not compare yourself to others — focus on YOUR improvement\n- Use the feedback to study better next time'),
  q(9, 'Thabo has a Maths test in five days. He plans to study a different section each day and review everything on the last day. Is this a good approach?',
    ['Yes — spreading study over several days with a final review is much more effective than cramming the night before', 'No — he should wait and study everything the night before when it is fresh', 'No — five days is too much preparation', 'It does not matter when you study — the result will be the same'], 0,
    'Spreading study over several days (spaced repetition) is one of the most effective learning strategies. The brain needs time to process and store information. Cramming the night before leads to poor recall and high stress.'),
  fb(10, 'Studying over several days instead of all at once is called spaced ___. Your brain stores memories while you ___.',
    ['repetition', 'sleep'],
    'Spaced repetition — reviewing material over increasing intervals — strengthens memory far more than cramming. Sleep is essential because the brain consolidates and stores memories during sleep.'),
];

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 5: Constitutional Rights and Responsibilities (Term 2, Weeks 1–2)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch5_lesson1 = [
  t(1, '## Constitutional Rights and Responsibilities\n\nThe South African Constitution is the highest law in the country. It was adopted in 1996 after the end of apartheid, and it protects the rights of every person in South Africa — including children.\n\n### Human Rights in the South African Constitution\n\nThe Bill of Rights is Chapter 2 of the Constitution. It lists the rights that belong to everyone in South Africa.\n\n**Key rights in the Bill of Rights:**\n\n| Right | Section | What it means |\n|-------|---------|---------------|\n| **Equality** | Section 9 | Everyone is equal before the law; no unfair discrimination |\n| **Human dignity** | Section 10 | Everyone has the right to be treated with respect |\n| **Life** | Section 11 | Everyone has the right to life |\n| **Freedom and security** | Section 12 | No one may be tortured or treated cruelly |\n| **Education** | Section 29 | Everyone has the right to basic education |\n| **Healthcare** | Section 27 | Everyone has the right to healthcare, food, water, and social security |\n| **Environment** | Section 24 | Everyone has the right to a healthy environment |\n| **Children\'s rights** | Section 28 | Children have special rights including protection from abuse and neglect |\n\n**Children\'s rights (Section 28):**\n- The right to family care or appropriate alternative care\n- The right to basic nutrition, shelter, healthcare, and social services\n- The right to be protected from abuse, neglect, maltreatment, and exploitation\n- The right not to be required to perform child labour\n- A child\'s best interests are of paramount importance in every matter concerning the child'),
  t(2, '### The Application of Human Rights\n\nRights are not just words on paper — they must be applied in everyday life:\n\n**Applying human rights at school:**\n\n| Right | How it applies at school |\n|-------|-----------------------|\n| **Equality** | All learners must be treated fairly regardless of race, gender, disability, or background |\n| **Dignity** | Teachers and learners must treat each other with respect — no bullying, humiliation, or name-calling |\n| **Education** | Every child has the right to attend school and receive quality education |\n| **Safety** | Schools must be safe spaces — no violence, weapons, or dangerous conditions |\n| **Expression** | Learners may express their views, but must do so respectfully |\n\n**Applying human rights in the community:**\n- Everyone deserves access to clean water, healthcare, and housing\n- No one may be discriminated against because of their race, religion, language, or gender\n- Children must be protected from abuse, labour, and exploitation\n- Everyone has the right to live in a safe environment\n\n**When rights are limited:**\nThe Constitution allows rights to be limited in certain situations if the limitation is reasonable and justifiable. For example:\n- Freedom of expression does not include the right to use hate speech\n- The right to freedom of movement does not mean you can trespass on private property'),
  q(3, 'Section 28 of the South African Constitution specifically protects the rights of which group?',
    ['Children — they have special rights including protection from abuse, neglect, and exploitation', 'Only adults over 18', 'Only citizens who have paid taxes', 'Only people who voted'], 0,
    'Section 28 of the Constitution gives children (people under 18) special rights. It recognises that children are vulnerable and need extra protection, including the right to family care, basic needs, and freedom from abuse and labour.'),
  t(4, '### Application of Responsibilities in Relation to Human Rights\n\nEvery right comes with a responsibility. You cannot demand rights without also fulfilling your responsibilities.\n\n**Rights and responsibilities go together:**\n\n| Right | Your responsibility |\n|-------|-------------------|\n| **Right to education** | Attend school, do your homework, respect teachers and classmates |\n| **Right to safety** | Do not bully, fight, or threaten others |\n| **Right to dignity** | Treat others with respect and dignity |\n| **Right to equality** | Do not discriminate against anyone |\n| **Right to a clean environment** | Do not litter, save water, care for the environment |\n| **Right to freedom of expression** | Express yourself without using hate speech or hurting others |\n\n**Responsibilities at school:**\n- Follow school rules and the code of conduct\n- Complete your work on time\n- Be punctual and attend every day\n- Wear your school uniform correctly\n- Take care of school property\n- Report problems to a teacher\n\n**Responsibilities at home:**\n- Help with household chores\n- Respect your parents or guardians\n- Take care of younger siblings\n- Study without being told\n- Communicate honestly with your family'),
  fb(5, 'The Bill of Rights is found in Chapter ___ of the South African Constitution. Every right comes with a ___.',
    ['2', 'responsibility'],
    'The Bill of Rights is Chapter 2 of the Constitution and contains all the fundamental rights. Rights and responsibilities go hand in hand — you cannot claim rights without fulfilling your responsibilities to others.'),
  t(6, '### Fair Play, Values, Trust, and Respect for Difference\n\nFair play is not just about sport — it is about how you treat people in every part of life.\n\n**What fair play means:**\n- Following the rules, even when no one is watching\n- Treating opponents and teammates with respect\n- Accepting decisions by teachers, referees, and authorities\n- Winning with humility and losing with grace\n- Giving everyone an equal chance to participate\n\n**Values that support fair play:**\n\n| Value | What it means in practice |\n|-------|-------------------------|\n| **Honesty** | Tell the truth, do not cheat, admit when you are wrong |\n| **Respect** | Treat everyone with dignity, even if you disagree |\n| **Responsibility** | Own up to your actions and their consequences |\n| **Compassion** | Show care for others, especially those in need |\n| **Fairness** | Treat everyone equally, do not show favouritism |\n| **Trust** | Be reliable — do what you say you will do |\n\n**Respect for difference:**\n- South Africa has many different cultures, languages, and religions\n- The Constitution protects everyone\'s right to their culture and religion\n- Respecting difference means listening, learning, and including others\n- Diversity is a strength, not a weakness'),
  q(7, 'During a soccer game, the referee makes a decision that Mandla disagrees with. What is the fair play response?',
    ['Accept the referee\'s decision respectfully — even if you disagree, the referee has the authority to make calls', 'Shout at the referee until the decision is changed', 'Walk off the field in protest', 'Refuse to play unless the referee agrees with you'], 0,
    'Fair play means accepting the decisions of authorities (referees, teachers, parents) even when you disagree. Mandla can express his view respectfully, but he must accept the decision and continue playing.'),
  t(8, '### Protecting Human Rights in Daily Life\n\nEvery person — including Grade 7 learners — has a role to play in protecting human rights:\n\n**What you can do:**\n- Speak up when you see someone being bullied or treated unfairly\n- Include learners who are excluded or lonely\n- Refuse to participate in discrimination (racial jokes, gender stereotypes, xenophobia)\n- Report abuse or violence to a trusted adult\n- Learn about the Constitution and teach others about their rights\n\n**Organisations that protect human rights:**\n\n| Organisation | What it does |\n|-------------|-------------|\n| **South African Human Rights Commission** | Investigates human rights violations |\n| **Commission for Gender Equality** | Promotes gender equality and investigates gender discrimination |\n| **Public Protector** | Investigates improper conduct by government officials |\n| **Children\'s rights organisations** | Childline, UNICEF, Nelson Mandela Children\'s Fund |\n\n**Remember:** You may be young, but you have the power to make a difference. Every time you stand up for someone, refuse to discriminate, or report an injustice, you are protecting human rights.'),
  q(9, 'A group of learners refuse to sit with a new classmate because she is from another country. Which human right is being violated?',
    ['The right to equality (Section 9) and the right to human dignity (Section 10) — no one should be excluded because of their nationality', 'The right to education', 'The right to healthcare', 'No right is being violated — it is just a preference'], 0,
    'Excluding someone because of their nationality is discrimination and violates the right to equality (Section 9) and human dignity (Section 10). It is also a form of xenophobia, which is unacceptable in South Africa.'),
  fb(10, 'The organisation that investigates human rights violations in South Africa is the South African ___ Rights Commission. Excluding someone because of their nationality is a form of ___.',
    ['Human', 'xenophobia'],
    'The South African Human Rights Commission investigates and resolves human rights violations. Xenophobia — hatred or prejudice against people from other countries — is a serious violation of human rights.'),
];

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 6: Dealing with Abuse (Term 2, Weeks 3–5)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch6_lesson1 = [
  t(1, '## Dealing with Abuse\n\nAbuse is when someone hurts another person physically, emotionally, or sexually. It can happen between adults and children, between peers, or between adults. This chapter helps you understand abuse, its effects, and where to find help.\n\n### What Is Abuse?\n\nAbuse can take many forms:\n\n| Type of abuse | What it looks like |\n|-------------|------------------|\n| **Physical abuse** | Hitting, slapping, kicking, burning, or any physical harm |\n| **Emotional abuse** | Constant criticism, shouting, threatening, humiliating, ignoring |\n| **Sexual abuse** | Unwanted touching, forcing sexual activity, showing inappropriate content |\n| **Neglect** | Not providing food, clothing, shelter, medical care, or supervision |\n| **Bullying** | Repeated aggressive behaviour — physical, verbal, or online |\n| **Child labour** | Forcing children to work instead of attending school |\n\n### Abuse in Different Contexts\n\n**Between adults and children:**\n- Adults (parents, relatives, teachers, strangers) who harm or exploit children\n- The adult is ALWAYS responsible — a child is NEVER to blame for abuse\n\n**Between peers (children and children):**\n- Bullying, cyberbullying, fighting, sexual harassment among learners\n\n**Between adults:**\n- Domestic violence between partners\n- This harms children who witness it — seeing violence is a form of abuse'),
  t(2, '### Effects of Abuse on Personal and Social Health and Relationships\n\nAbuse causes deep harm to every part of a person\'s life:\n\n**Emotional effects:**\n- Fear, anxiety, and depression\n- Low self-esteem and feelings of worthlessness\n- Anger and difficulty trusting people\n- Nightmares and difficulty sleeping\n- Difficulty concentrating at school\n\n**Physical effects:**\n- Injuries (bruises, broken bones, burns)\n- Health problems from neglect (malnutrition, untreated illnesses)\n- Physical symptoms of stress (headaches, stomachaches)\n\n**Social effects:**\n- Withdrawal from friends and family\n- Difficulty forming healthy relationships\n- Aggressive or disruptive behaviour at school\n- Running away from home\n- Risk of substance abuse as a coping mechanism\n\n**The cycle of violence:**\nChildren who grow up with abuse may repeat the pattern as adults unless they get help. Breaking the cycle requires:\n- Recognising that abuse is wrong\n- Getting professional counselling\n- Learning healthy ways to express anger and frustration\n- Building positive relationships based on respect'),
  q(3, 'Which of the following is an example of emotional abuse?',
    ['A parent constantly tells a child "You are useless and will never amount to anything"', 'A parent helps a child with homework', 'A teacher gives a learner a fair consequence for breaking a rule', 'A friend asks you to play together'], 0,
    'Emotional abuse involves constant criticism, humiliation, and degrading language that damages a child\'s self-worth. Telling a child they are "useless" and will "never amount to anything" is emotional abuse.'),
  t(4, '### Communication to Promote Healthy and Non-Violent Relationships\n\nHealthy relationships are based on respect, trust, and good communication — never on fear or control.\n\n**Signs of a healthy relationship:**\n- You feel safe and respected\n- You can express your feelings without fear\n- Disagreements are resolved through talking, not violence\n- Both people are treated as equals\n\n**Signs of an unhealthy or abusive relationship:**\n- One person controls or dominates the other\n- There is physical, emotional, or verbal violence\n- You feel afraid of the other person\n- You are isolated from friends and family\n- You are constantly criticised or put down\n\n**Communication skills for non-violent relationships:**\n- Use "I feel..." statements instead of blaming: "I feel hurt when you shout at me"\n- Listen without interrupting\n- Express anger without violence — walk away, cool down, then talk\n- Respect boundaries — if someone says stop, STOP\n- Solve problems together through discussion, not fights\n\n**Importance of communication:**\nGood communication prevents misunderstandings and reduces conflict. It is one of the most powerful tools for building and maintaining healthy relationships.'),
  fb(5, 'Children who grow up with abuse may repeat the pattern as adults — this is called the ___ of violence. Using "I feel..." statements instead of blaming is a skill for ___ communication.',
    ['cycle', 'healthy'],
    'The cycle of violence refers to the pattern where children who experience abuse may become abusers themselves as adults. Healthy communication uses "I feel" statements to express emotions without blaming others.'),
  t(6, '### How to Protect Yourself from Threatening and Risky Situations\n\nKnowing how to stay safe is a critical life skill:\n\n**Personal safety rules:**\n- Trust your instincts — if something feels wrong, it probably is\n- Your body belongs to you — nobody has the right to touch you inappropriately\n- There are no "good" secrets about touching — if an adult tells you to keep touching a secret, that is wrong\n- Always tell a trusted adult if someone hurts you or makes you uncomfortable\n- Never go anywhere with a stranger, even if they say they know your parents\n- Travel in groups, not alone, especially after dark\n\n**Online safety:**\n- Never share personal information online (address, school, phone number)\n- Do not chat with strangers online — they may not be who they say they are\n- Never send or share photos of yourself that you would not want everyone to see\n- Tell an adult if someone online makes you uncomfortable\n- Block and report bullies or people who send inappropriate messages\n\n**Safety at school:**\n- Report bullying, fighting, and harassment to a teacher immediately\n- Do not bring weapons or dangerous items to school\n- Stay in supervised areas during break times\n- Know the school\'s emergency procedures'),
  q(7, 'An older person tells a child, "This is our special secret — do not tell anyone." What should the child do?',
    ['Tell a trusted adult immediately — secrets about touching or inappropriate behaviour are NOT safe secrets', 'Keep the secret because the person said to', 'Wait to see if it happens again before telling someone', 'Ignore it and hope it stops'], 0,
    'There is no such thing as a "good secret" about touching or inappropriate behaviour. If any person — adult or peer — tells a child to keep touching or uncomfortable behaviour a secret, the child should tell a trusted adult immediately.'),
  t(8, '### Places of Protection and Safety, and Where to Find Help\n\nIf you or someone you know is being abused, there are people and places that can help:\n\n**Helplines (free and confidential):**\n\n| Organisation | Number | Services |\n|-------------|--------|----------|\n| **Childline** | 0800 055 555 | Counselling, reporting abuse, referral to social workers |\n| **SAPS Emergency** | 10111 | Report crimes, get emergency help |\n| **Lifeline** | 0861 322 322 | Crisis counselling for anyone |\n| **Stop Gender Violence** | 0800 150 150 | GBV support and reporting |\n| **SADAG** | 0800 567 567 | Mental health support |\n\n**Places of safety:**\n- Police stations — you can report abuse and get a protection order\n- Hospitals and clinics — for medical care and reporting abuse\n- Social workers at the Department of Social Development\n- Children\'s courts — can place abused children in safe care\n- Shelters — safe places for women and children fleeing abuse\n- Schools — teachers are legally required to report suspected abuse\n\n**The Children\'s Act (Act 38 of 2005):**\nThis law protects children from abuse, neglect, and exploitation. It requires certain people (teachers, doctors, social workers) to report suspected child abuse. Failure to report is a crime.'),
  q(9, 'According to South African law, who is legally required to report suspected child abuse?',
    ['Teachers, doctors, and social workers are all legally required to report suspected abuse', 'Only the police can report abuse', 'Only the child\'s parents can report', 'Nobody is required to report — it is optional'], 0,
    'The Children\'s Act requires professionals who work with children (teachers, doctors, social workers, nurses) to report suspected child abuse. Failure to report is itself a criminal offence.'),
  fb(10, 'The law that protects children from abuse, neglect, and exploitation in South Africa is called the ___ Act. The free Childline number to report abuse is ___.',
    ['Children\'s', '0800 055 555'],
    'The Children\'s Act (Act 38 of 2005) is the primary legislation protecting children in South Africa. Childline (0800 055 555) provides free, confidential counselling and referrals for abused or at-risk children.'),
];

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 7: Career Fields and the World of Work (Term 2, Weeks 6–9)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch7_lesson1 = [
  t(1, '## Career Fields and the World of Work\n\nIt is never too early to start thinking about your future career. In Grade 7, you begin exploring different career fields, the qualifications they require, and how your school subjects connect to the world of work.\n\n### What Is a Career Field?\n\nA career field is a broad area of work that includes many related jobs. Understanding career fields helps you see the wide range of opportunities available.\n\n**Major career fields in South Africa:**\n\n| Career field | Examples of careers |\n|-------------|-------------------|\n| **Healthcare** | Doctor, nurse, pharmacist, dentist, paramedic, physiotherapist |\n| **Education** | Teacher, lecturer, school counsellor, education researcher |\n| **Engineering and Technology** | Civil engineer, IT specialist, software developer, electrician |\n| **Business and Finance** | Accountant, banker, entrepreneur, marketing manager |\n| **Law and Justice** | Lawyer, magistrate, police officer, human rights activist |\n| **Agriculture** | Farmer, agricultural scientist, veterinarian, food technologist |\n| **Arts and Creative Industries** | Musician, graphic designer, journalist, actor, photographer |\n| **Social Services** | Social worker, psychologist, community developer |'),
  t(2, '### Qualities Relating to Each Career Field: Interests and Abilities\n\nDifferent careers require different qualities, interests, and abilities:\n\n| Career field | Key qualities needed |\n|-------------|--------------------|\n| **Healthcare** | Caring, patience, attention to detail, ability to work under pressure, good at Science |\n| **Education** | Communication skills, patience, love of learning, ability to explain things clearly |\n| **Engineering** | Problem-solving, logical thinking, good at Maths and Science, creativity |\n| **Business** | Leadership, communication, numeracy, decision-making, confidence |\n| **Law** | Critical thinking, strong language skills, fairness, research ability |\n| **Agriculture** | Love of nature, practical skills, patience, scientific knowledge |\n| **Arts** | Creativity, imagination, dedication, willingness to practise |\n| **Social services** | Empathy, listening skills, patience, emotional strength |\n\n**How to match your interests to a career field:**\n- If you enjoy helping sick people → Healthcare\n- If you enjoy explaining things to others → Education\n- If you enjoy building and fixing things → Engineering\n- If you enjoy numbers and managing money → Business and Finance\n- If you enjoy arguments and debate → Law\n- If you enjoy drawing, music, or writing → Arts'),
  q(3, 'Nomvula is patient, caring, good at Science, and wants to help sick people get better. Which career field is the best match for her?',
    ['Healthcare — her caring nature and science ability match perfectly with careers like nursing or medicine', 'Arts and Creative Industries', 'Business and Finance', 'Law and Justice'], 0,
    'Nomvula\'s combination of a caring personality, patience, and science ability points clearly to the healthcare career field. She could consider becoming a doctor, nurse, pharmacist, or physiotherapist.'),
  t(4, '### School Subjects Related to Each Career Field\n\nThe subjects you study at school connect directly to career opportunities:\n\n| Career field | Important school subjects |\n|-------------|------------------------|\n| **Healthcare** | Life Sciences, Physical Sciences, Mathematics |\n| **Education** | Languages, all subjects (teachers can teach any subject) |\n| **Engineering** | Mathematics, Physical Sciences, Technology |\n| **Business** | Economic and Management Sciences (EMS), Mathematics, Languages |\n| **Law** | Languages (English, Afrikaans, home language), Social Sciences |\n| **Agriculture** | Natural Sciences, Geography, Mathematics |\n| **Arts** | Creative Arts, Languages, Technology |\n| **Social services** | Life Orientation, Languages, Social Sciences |\n\n**Important advice for Grade 7 learners:**\n- Take ALL your subjects seriously — you do not know which ones you will need in the future\n- Mathematics is the most important subject for keeping career options open\n- Strong language skills are needed in EVERY career\n- Ask your LO teacher about career guidance resources\n\n### Work Environment and Activities in Each Career Field\n\n| Career field | Typical work environment |\n|-------------|------------------------|\n| **Healthcare** | Hospitals, clinics, private practices, laboratories |\n| **Education** | Schools, universities, training centres |\n| **Engineering** | Offices, construction sites, factories, mines |\n| **Business** | Offices, shops, banks, markets |\n| **Law** | Courts, law firms, government offices |\n| **Agriculture** | Farms, laboratories, food processing plants |\n| **Arts** | Studios, theatres, media houses, home offices |'),
  fb(5, 'The school subject that keeps the most career options open is ___. Strong ___ skills are needed in every career.',
    ['Mathematics', 'language'],
    'Mathematics is the foundation for careers in science, engineering, technology, business, and more. Language skills (reading, writing, speaking) are essential in every profession for communication.'),
  t(6, '### Opportunities, Challenges, and Requirements\n\nEvery career field has opportunities and challenges:\n\n**Opportunities in the South African job market:**\n- Healthcare workers are in high demand, especially in rural areas\n- South Africa has a severe shortage of Maths and Science teachers\n- The technology sector is growing rapidly — IT skills are highly valued\n- Entrepreneurship creates jobs and addresses unemployment\n- Agriculture is essential for food security\n\n**Challenges:**\n- High unemployment rate, especially among youth\n- Many careers require expensive qualifications\n- Some areas have limited job opportunities\n- Competition for popular careers (law, medicine) is intense\n\n**Level of schooling and duration of study:**\n\n| Qualification | Duration | Examples |\n|--------------|----------|----------|\n| **Matric (Grade 12)** | 12 years of school | Needed for most jobs |\n| **Certificate** | 6 months – 1 year after matric | Receptionist, security, basic IT |\n| **Diploma** | 2–3 years after matric | Nursing, engineering technician, marketing |\n| **Degree** | 3–4 years after matric | Teaching, accounting, social work |\n| **Professional degree** | 5–7 years after matric | Medicine, law, engineering, veterinary science |'),
  q(7, 'Which of the following career fields has one of the biggest shortages in South Africa?',
    ['Healthcare workers (especially in rural areas) and Maths/Science teachers', 'Professional athletes', 'Social media influencers', 'Fashion models'], 0,
    'South Africa faces critical shortages in healthcare (especially in rural clinics and hospitals) and education (particularly Mathematics and Science teachers). These fields offer strong career opportunities.'),
  t(8, '### Services, Sources, and Career Information\n\nThere are many resources to help you explore careers:\n\n**Career information sources:**\n- **School LO teacher** — your first source of career guidance\n- **Career exhibitions** — attend career days and expos at schools and community centres\n- **Library** — career guide books and information pamphlets\n- **Internet** — websites like www.careerhelp.org.za\n- **Career helpline** — 086 999 0123 (free career guidance by phone)\n- **Job shadowing** — spend a day watching someone do their job\n- **Interviews** — ask family members, neighbours, or community members about their careers\n\n**Questions to ask about a career:**\n1. What does a typical day look like?\n2. What subjects did you need at school?\n3. Where did you study and for how long?\n4. What do you enjoy most about your work?\n5. What are the biggest challenges?\n6. What advice would you give a Grade 7 learner interested in this career?\n\n**The value and importance of work:**\n- Work provides income to meet your needs and those of your family\n- Work gives you a sense of purpose and achievement\n- Working people contribute to the economy through paying taxes\n- Work builds skills, confidence, and social connections\n- Fulfilling work contributes to your personal needs and potential'),
  q(9, 'What is "job shadowing"?',
    ['Spending a day watching and learning from someone doing a job you are interested in', 'Following someone home from work', 'Copying someone else\'s CV and applying for the same job', 'Working two jobs at the same time'], 0,
    'Job shadowing is when you spend time observing someone at their workplace to learn what the job involves. It is an excellent way for young people to explore career options and see what a career is really like.'),
  fb(10, 'The free career helpline number in South Africa is ___. Spending a day watching someone do their job to learn about it is called job ___.',
    ['086 999 0123', 'shadowing'],
    'The career helpline at 086 999 0123 provides free career guidance. Job shadowing allows you to experience a career firsthand by observing a professional at work.'),
];

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 8: Substance Abuse (Term 3, Weeks 1–3)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch8_lesson1 = [
  t(1, '## Substance Abuse Awareness\n\nSubstance abuse is a serious problem among young people in South Africa. Understanding the types of substances, their symptoms, and how to protect yourself is an important life skill.\n\n### What Is Substance Abuse?\n\nSubstance abuse is the harmful use of substances that affect the way your body and mind work. It includes:\n\n- Using illegal drugs (dagga/marijuana, tik/methamphetamine, nyaope, cocaine)\n- Misusing legal substances (alcohol, cigarettes, over-the-counter medicines, glue/aerosols)\n- Using tobacco products (cigarettes, hubbly bubbly, vapes/e-cigarettes)\n\n### Types and Forms of Substance Abuse\n\n| Substance | Form | How it is used |\n|-----------|------|---------------|\n| **Alcohol** | Beer, wine, spirits, homebrewed liquor | Drinking |\n| **Tobacco** | Cigarettes, snuff, hubbly bubbly, vapes | Smoking, chewing, inhaling |\n| **Dagga (marijuana)** | Dried leaves, cookies, oil | Smoking, eating |\n| **Tik (methamphetamine)** | Crystal/powder | Smoking in a lightbulb, snorting |\n| **Nyaope** | Mixture of heroin and other substances | Smoking, injecting |\n| **Inhalants** | Glue, petrol, aerosol sprays, thinners | Sniffing/huffing |\n| **Over-the-counter drugs** | Cough syrup, painkillers, diet pills | Swallowing in large doses |'),
  t(2, '### Symptoms of Substance Abuse\n\nKnowing the warning signs of substance abuse can help you recognise it in yourself or others:\n\n**Physical symptoms:**\n- Red or glassy eyes\n- Sudden weight loss or weight gain\n- Poor hygiene (not bathing, dirty clothes)\n- Unusual smells on breath, body, or clothing\n- Shaking hands or unsteady walking\n- Unexplained injuries\n\n**Behavioural symptoms:**\n- Sudden change in friends or social group\n- Drop in school marks and missing school\n- Secretive behaviour, lying, or stealing\n- Mood swings — extreme happiness followed by extreme sadness or anger\n- Loss of interest in hobbies, sport, and activities\n- Sleeping too much or too little\n\n**Psychological symptoms:**\n- Confusion and difficulty concentrating\n- Paranoia (feeling everyone is out to get you)\n- Depression, anxiety, or hopelessness\n- Aggressive or violent behaviour\n- Memory problems\n\n**If you notice these signs in a friend:**\n- Talk to them privately and express your concern\n- Do not judge or shame them\n- Encourage them to talk to a trusted adult\n- Tell a teacher or counsellor if you are worried about their safety'),
  q(3, 'Jabu has noticed that his friend Tshepo has red eyes, has started missing school, and has a new group of friends that Jabu does not know. What might these signs indicate?',
    ['Possible substance abuse — these are common warning signs that Tshepo may need help', 'Tshepo is just going through a normal phase', 'Tshepo is studying harder with new friends', 'Nothing — these signs are not important'], 0,
    'Red eyes, missing school, and sudden changes in friend groups are common warning signs of substance abuse. Jabu should talk to Tshepo privately and consider telling a trusted adult if he is concerned.'),
  t(4, '### Personal Factors That Contribute to Substance Abuse\n\nMany personal factors can increase the risk of substance abuse:\n\n**Risk factors (intrapersonal):**\n- Low self-esteem — using substances to feel "cool" or fit in\n- Curiosity — wanting to try something new and exciting\n- Stress and emotional pain — using substances to escape problems\n- Boredom — having nothing to do and looking for thrills\n- Mental health problems — depression, anxiety, trauma\n\n**Risk factors (interpersonal):**\n- Peer pressure — friends encouraging substance use\n- Family problems — parents who abuse substances, domestic violence, neglect\n- Easy access — living near taverns, shebeens, or drug dealers\n- Poverty — desperation and lack of opportunities\n- Lack of positive role models\n\n**Protective factors that reduce the likelihood of substance abuse:**\n\n| Protective factor | How it helps |\n|------------------|-------------|\n| **Strong family bonds** | Feeling loved and supported at home |\n| **Positive friends** | Friends who do not use substances and encourage good behaviour |\n| **High self-esteem** | Feeling confident enough to say no |\n| **School involvement** | Being busy with school, sport, clubs, and activities |\n| **Clear goals** | Having something to work towards |\n| **Knowledge** | Understanding the real dangers of substances |\n| **Trusted adults** | Having adults you can talk to about problems |'),
  fb(5, 'Feeling loved and supported at home is a ___ factor that protects against substance abuse. The most commonly used illegal drug among South African youth is ___.',
    ['protective', 'dagga'],
    'Protective factors are conditions that reduce the risk of substance abuse. Strong family bonds provide emotional security. Dagga (marijuana/cannabis) is the most widely used illegal substance among young people in South Africa.'),
  t(6, '### Prevention Measures: Early Detection\n\nPrevention is always better than treatment:\n\n**Primary prevention — stopping substance abuse before it starts:**\n- Education about the dangers of substances (what you are learning now)\n- Building refusal skills — knowing how to say no\n- Strengthening protective factors (family bonds, self-esteem, positive activities)\n- Community awareness campaigns\n\n**Early detection — recognising problems early:**\n- Pay attention to warning signs in yourself and others\n- Take action quickly — the earlier the problem is addressed, the better the outcome\n- Do not wait for the problem to get worse — speak up\n\n**Refusal skills — how to say NO:**\n1. Be direct: "No thank you, I do not use that"\n2. Give a reason: "No, I want to stay healthy for my sport"\n3. Suggest an alternative: "Let us play basketball instead"\n4. Walk away — you have the right to leave any uncomfortable situation\n5. Use the broken record: "No. No. I said no."\n\n**If you or someone you know needs help:**\n\n| Organisation | Number |\n|-------------|--------|\n| **SANCA** (South African National Council on Alcoholism and Drug Dependence) | 011 892 3829 |\n| **Childline** | 0800 055 555 |\n| **Lifeline** | 0861 322 322 |\n| **SADAG** | 0800 567 567 |'),
  q(7, 'What is the BEST way to prevent substance abuse in young people?',
    ['A combination of education, building refusal skills, strengthening protective factors, and having trusted adults to talk to', 'Just telling young people to say no without explaining why', 'Ignoring the problem and hoping it goes away', 'Only punishing people who use substances'], 0,
    'Effective prevention uses multiple strategies: education about dangers, building skills to refuse pressure, strengthening protective factors (family, self-esteem, goals), and ensuring young people have trusted adults they can turn to.'),
  t(8, '### The Impact of Substance Abuse on Young People\n\nSubstance abuse is especially harmful to young people because their brains and bodies are still developing:\n\n**Impact on the brain:**\n- The brain continues developing until about age 25\n- Substances can cause permanent damage to brain development\n- Memory, concentration, and learning ability are all affected\n- Risk of mental health problems (depression, psychosis) increases\n\n**Impact on school performance:**\n- Cannot concentrate in class\n- Absent from school frequently\n- Drop in marks and possible failure\n- Conflict with teachers and suspension or expulsion\n\n**Impact on relationships:**\n- Damaged trust with family members\n- Loss of positive friendships\n- Isolation and loneliness\n- Association with negative peer groups\n\n**Impact on the future:**\n- Criminal record from drug offences\n- Health problems that last a lifetime\n- Difficulty finding employment\n- Broken dreams and lost potential\n\n**The truth about substances:**\n- They do NOT make you cooler, smarter, or more popular\n- The "fun" is temporary, but the damage can be permanent\n- Addiction can start from just one try\n- There are much better ways to have fun, cope with stress, and fit in'),
  q(9, 'Why is substance abuse ESPECIALLY dangerous for Grade 7 learners compared to adults?',
    ['Because the teenage brain is still developing until about age 25, making it more vulnerable to permanent damage and faster addiction', 'Because teenagers are physically stronger than adults', 'Because substances affect teenagers less than adults', 'Because the law does not apply to teenagers'], 0,
    'The adolescent brain continues developing until approximately age 25. Substance use during this critical period can cause permanent damage to brain development and leads to faster, stronger addiction than in adults.'),
  fb(10, 'The brain continues developing until about age ___. SANCA stands for the South African National Council on Alcoholism and ___ Dependence.',
    ['25', 'Drug'],
    'The human brain is not fully developed until approximately age 25, which is why substance use during adolescence is particularly harmful. SANCA provides treatment and prevention services for substance abuse.'),
];

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 9: Environmental Health (Term 3, Weeks 4–7)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch9_lesson1 = [
  t(1, '## Environmental Health\n\nThe environment around us directly affects our health. In South Africa, many communities face environmental problems that cause illness and reduce quality of life. This chapter explores environmental health issues and what you can do to make a difference.\n\n### What Is Environmental Health?\n\nEnvironmental health is about the relationship between the environment and human health. A clean, safe environment promotes good health; a polluted, neglected environment causes disease.\n\n### Local Environmental Health Problems\n\n**Common environmental problems in South African communities:**\n\n| Problem | Health impact |\n|---------|-------------|\n| **Water pollution** | Dirty water causes cholera, diarrhoea, and other waterborne diseases |\n| **Air pollution** | Smoke from fires, factories, and vehicles causes asthma, bronchitis, and lung disease |\n| **Littering and illegal dumping** | Attracts rats, flies, and mosquitoes that spread disease |\n| **Poor sanitation** | Lack of proper toilets leads to waterborne diseases and infections |\n| **Overcrowding** | Diseases spread more easily in crowded living conditions |\n| **Lack of clean water** | Forces people to use unsafe water sources |\n| **Deforestation** | Leads to soil erosion, flooding, and loss of natural resources |\n\n**In your community:**\nThink about the environmental health problems in your own neighbourhood. Are there blocked drains? Illegal dump sites? Smoke pollution? Unsafe water?'),
  t(2, '### Community and Individual Projects to Deal with Environmental Health Problems\n\nYou do not have to wait for the government to solve environmental problems — individuals and communities can take action:\n\n**What individuals can do:**\n- Do not litter — always use a bin or take your rubbish home\n- Save water — close taps properly, take shorter showers, report leaks\n- Save electricity — switch off lights, unplug devices, use natural light\n- Reduce, reuse, recycle — the three Rs of waste management\n- Plant trees and gardens — they clean the air and prevent soil erosion\n- Walk or cycle instead of driving — reduces air pollution\n\n**What communities can do:**\n- Organise neighbourhood clean-up campaigns\n- Set up recycling collection points\n- Start community vegetable gardens\n- Report illegal dumping and pollution to the municipality\n- Hold awareness events about environmental health\n- Work with local schools to create eco-clubs\n\n**The three Rs explained:**\n\n| R | What it means | Examples |\n|---|--------------|----------|\n| **Reduce** | Use less | Buy less packaging, use reusable bags, avoid single-use plastic |\n| **Reuse** | Use again | Refill water bottles, donate old clothes, use containers instead of plastic bags |\n| **Recycle** | Make new from old | Separate paper, plastic, glass, and metal for recycling collection |'),
  q(3, 'Your neighbourhood has a problem with illegal dumping. What is the BEST first step to address this?',
    ['Report it to the municipality and organise a community clean-up while educating neighbours about proper waste disposal', 'Ignore it because it is the government\'s responsibility', 'Move to a different neighbourhood', 'Add your own rubbish to the dump site'], 0,
    'Environmental problems require both individual and collective action. Reporting illegal dumping to the municipality triggers official action, while community clean-ups and education address the problem directly.'),
  t(4, '### Problem-Solving Skills: Developing an Action Plan\n\nYou can make a real difference in your community by developing an environmental health action plan:\n\n**Steps to create an action plan:**\n\n| Step | What to do |\n|------|----------|\n| **1. Identify** | What is the environmental problem? Where is it? How bad is it? |\n| **2. Research** | What causes the problem? What are the health effects? What solutions have worked elsewhere? |\n| **3. Plan** | What actions will you take? Who will help? What resources do you need? When will you do it? |\n| **4. Act** | Put your plan into action |\n| **5. Evaluate** | Did it work? What could be improved? What next? |\n\n**Example action plan: Reducing litter at school**\n\n| Element | Detail |\n|---------|-------|\n| **Problem** | Litter in the school grounds, especially after break time |\n| **Goal** | Reduce litter by 80% within one term |\n| **Actions** | Place more bins, create anti-litter posters, assign class clean-up duties, start recycling programme |\n| **Resources** | Extra bins (ask school), poster materials, volunteer monitors |\n| **Timeline** | Start Week 1, evaluate at end of term |\n| **Evaluation** | Photograph the grounds weekly to track improvement |'),
  fb(5, 'The three Rs of waste management are reduce, reuse, and ___. An environmental action plan starts with ___ the problem.',
    ['recycle', 'identifying'],
    'The three Rs — reduce, reuse, recycle — are practical strategies for managing waste. Every action plan begins with clearly identifying the problem you want to solve.'),
  t(6, '### Formulating Environmentally Sound Choices and Actions\n\nEvery choice you make affects the environment. Making environmentally sound choices means choosing options that protect rather than harm the environment:\n\n**Environmentally sound choices at school:**\n- Use both sides of paper before recycling it\n- Switch off lights and devices when not in use\n- Do not waste water in the bathrooms\n- Keep the school grounds clean\n- Start or join an eco-club\n\n**Environmentally sound choices at home:**\n- Take shorter showers (5 minutes or less)\n- Turn off the tap while brushing your teeth\n- Separate waste for recycling\n- Compost fruit and vegetable scraps\n- Use reusable shopping bags instead of plastic bags\n- Plant indigenous trees and plants\n\n**South Africa\'s environmental laws:**\n- Section 24 of the Bill of Rights: everyone has the right to a healthy environment\n- The National Environmental Management Act (NEMA) sets rules for environmental protection\n- Littering, illegal dumping, and pollution are all offences that can lead to fines or jail time\n\n**Remember:** The environment does not belong to us — we borrow it from future generations. The choices you make today will determine the world your children and grandchildren live in.'),
  q(7, 'Which section of the South African Bill of Rights protects everyone\'s right to a healthy environment?',
    ['Section 24 — the right to an environment that is not harmful to health or well-being', 'Section 9 — the right to equality', 'Section 29 — the right to education', 'Section 11 — the right to life'], 0,
    'Section 24 of the Bill of Rights specifically addresses environmental rights. It states that everyone has the right to an environment that is not harmful to their health or well-being.'),
  t(8, '### Water Conservation in South Africa\n\nSouth Africa is a water-scarce country. Conserving water is everyone\'s responsibility:\n\n**Why water conservation matters:**\n- South Africa is one of the 30 driest countries in the world\n- Many communities do not have reliable access to clean water\n- Droughts are becoming more frequent due to climate change\n- Water is essential for life, agriculture, and the economy\n\n**How to save water:**\n\n| Action | Water saved |\n|--------|----------|\n| Fix a dripping tap | Up to 30 litres per day |\n| Take a 5-minute shower instead of a bath | Up to 100 litres per shower |\n| Turn off the tap while brushing teeth | Up to 6 litres per brushing |\n| Use a bucket to wash a car instead of a hosepipe | Up to 300 litres per wash |\n| Collect rainwater for the garden | Saves tap water |\n| Water the garden in the early morning or evening | Less water lost to evaporation |\n\n**Remember:** Water is a precious resource. Every drop you save helps ensure there is enough for everyone — now and in the future.'),
  q(9, 'Why is South Africa described as a "water-scarce" country?',
    ['Because South Africa has limited freshwater resources and is one of the 30 driest countries in the world', 'Because it rains every day in South Africa', 'Because South Africa has too many rivers', 'Because South Africans waste all their water'], 0,
    'South Africa has limited freshwater resources and receives less rainfall than the world average. Combined with a growing population and climate change, this makes water conservation essential.'),
  fb(10, 'South Africa is one of the ___ driest countries in the world. Fixing a dripping tap can save up to ___ litres of water per day.',
    ['30', '30'],
    'South Africa ranks among the 30 driest countries globally. A single dripping tap can waste up to 30 litres of water per day — showing that small actions can make a big difference in conservation.'),
];

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 10: Career Simulation and the Value of Work (Term 3, Weeks 8–11)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch10_lesson1 = [
  t(1, '## Career Simulation Activities\n\nA career simulation is an activity where you "pretend" to work in a specific career to understand what it involves. In Grade 7, you will explore a chosen career field in depth by researching and presenting key aspects of that career.\n\n### Name of Career and Who Is the Employer\n\nWhen researching a career, start with the basics:\n\n**Questions to answer:**\n- What is the official name of the career? (e.g., "Registered Nurse" not just "nurse")\n- Who employs people in this career? (Government hospital, private company, school, themselves)\n- Is the employer typically public (government) or private sector?\n- Can you be self-employed in this career? (e.g., a lawyer can start their own firm)\n\n**Types of employers in South Africa:**\n\n| Employer type | Examples |\n|-------------|----------|\n| **Government** | Schools, hospitals, police, municipality offices |\n| **Private companies** | Mines, banks, retail shops, factories, law firms |\n| **Non-profit organisations** | NGOs, charities, community organisations |\n| **Self-employment** | Own business, freelancing, farming |'),
  t(2, '### Dress Code, Tools, and Activities\n\nEvery career has specific requirements for how you dress and what you use:\n\n**Dress code:**\n- Some careers require uniforms (nurses, police, chefs, soldiers)\n- Some require formal business wear (lawyers, bankers, managers)\n- Some allow casual or creative dress (graphic designers, artists)\n- Some require safety clothing (construction workers, miners, electricians)\n\n**Tools or working equipment:**\n\n| Career | Tools and equipment |\n|--------|-------------------|\n| **Doctor** | Stethoscope, medical instruments, computers |\n| **Electrician** | Wire cutters, testers, safety gear |\n| **Teacher** | Textbooks, whiteboard, computer, stationery |\n| **Chef** | Knives, pots, stove, ingredients |\n| **Software developer** | Computer, software programmes, internet |\n| **Farmer** | Tractor, seeds, irrigation equipment |\n\n**Activities related to the career:**\n- What does a person in this career DO every day?\n- What are the main tasks and responsibilities?\n- Is the work mostly practical (hands-on) or theoretical (thinking, planning, writing)?\n- Does the work involve interacting with people, working with machines, or both?'),
  q(3, 'A learner is doing a career simulation for "paramedic." Which of the following would be part of the simulation?',
    ['Wearing a uniform, practising first aid, and responding to a simulated emergency scenario', 'Sitting at a desk and typing reports all day', 'Designing fashion outfits', 'Cooking meals in a restaurant'], 0,
    'Paramedics wear uniforms, provide emergency medical care, and respond to emergencies. A career simulation would involve practising these elements to understand what the career is really like.'),
  t(4, '### Personality Characteristics for Different Careers\n\nYour personality plays a big role in which careers will suit you best:\n\n| Personality trait | Careers it suits |\n|------------------|------------------|\n| **Caring and patient** | Nurse, teacher, social worker, counsellor |\n| **Brave and quick-thinking** | Paramedic, firefighter, police officer, soldier |\n| **Creative and imaginative** | Artist, writer, designer, architect, musician |\n| **Organised and detail-oriented** | Accountant, administrator, pharmacist, librarian |\n| **Outgoing and persuasive** | Salesperson, lawyer, politician, marketing manager |\n| **Analytical and curious** | Scientist, engineer, researcher, detective |\n| **Practical and hands-on** | Mechanic, electrician, farmer, chef, builder |\n\n**Understanding your own personality:**\n- Are you an introvert (prefer quiet, smaller groups) or extrovert (prefer socialising, larger groups)?\n- Do you prefer working with people, data, or things?\n- Do you like routine or variety?\n- Are you a leader or do you prefer following instructions?\n\nThere is no "right" or "wrong" personality — every personality type has careers that match it perfectly.'),
  fb(5, 'A person who is caring, patient, and enjoys helping others would suit careers in the ___ or teaching fields. People who are analytical and curious might enjoy being a scientist or ___.',
    ['healthcare', 'engineer'],
    'Caring, patient people thrive in healthcare and education. Analytical, curious minds are well-suited to scientific research and engineering where they can investigate and solve problems.'),
  t(6, '### Requirements, Duration of Study, and Where to Study\n\nUnderstanding the requirements for a career helps you plan your path:\n\n**Level of schooling required:**\n\n| Career | Minimum qualification | Duration after Grade 12 |\n|--------|---------------------|------------------------|\n| **Police officer** | Matric + police training | 6–12 months training |\n| **Nurse** | Matric with Science | 3–4 years (diploma or degree) |\n| **Teacher** | Matric | 4 years (B.Ed. degree) |\n| **Accountant** | Matric with Maths | 3–4 years (degree) + articles |\n| **Doctor** | Matric with Maths and Science | 6 years (MBChB degree) + internship |\n| **Lawyer** | Matric with strong languages | 4 years (LLB degree) + articles |\n| **Electrician** | Matric or Grade 9 | 3–4 years (apprenticeship + trade test) |\n\n**Where to study in South Africa:**\n- **Universities** — degrees (UCT, Wits, Stellenbosch, UKZN, UJ, etc.)\n- **TVET Colleges** — diplomas and certificates (practical, hands-on training)\n- **Private colleges** — specialised courses (IT, hospitality, beauty)\n- **Learnerships** — study and work at the same time (employer provides training)\n- **SETA programmes** — government-funded training programmes\n\n**Financial support:**\n- NSFAS (National Student Financial Aid Scheme) — bursaries for students who cannot afford fees\n- Bursaries from companies and organisations\n- Scholarships based on academic achievement'),
  q(7, 'Ayanda wants to become a teacher. What qualification does she need and how long will it take?',
    ['A Bachelor of Education (B.Ed.) degree, which takes 4 years of full-time study after Grade 12', 'Only a Matric certificate — no further study is needed', 'A 6-month certificate course', 'A medical degree'], 0,
    'To become a qualified teacher in South Africa, Ayanda needs a Bachelor of Education (B.Ed.) degree, which is a 4-year university qualification. Some teachers also complete a PGCE (1 year) after a different degree.'),
  t(8, '### Related Careers and the Value of Work\n\nEvery career field has related careers — knowing about them broadens your options:\n\n**Examples of related careers:**\n\n| Main career | Related careers |\n|------------|----------------|\n| **Doctor** | Nurse, pharmacist, physiotherapist, radiographer, paramedic |\n| **Teacher** | Lecturer, tutor, education psychologist, curriculum developer |\n| **Lawyer** | Paralegal, magistrate, mediator, human rights activist |\n| **Chef** | Baker, food scientist, restaurant manager, food photographer |\n| **Engineer** | Technician, architect, surveyor, project manager |\n\n**The value and importance of work in fulfilling personal needs and potential:**\n- **Financial needs** — work provides income for food, housing, education, and recreation\n- **Social needs** — work connects you with other people and builds community\n- **Emotional needs** — meaningful work gives purpose, pride, and satisfaction\n- **Growth needs** — work develops your skills and helps you reach your potential\n- **Contribution** — through work, you contribute to your family, community, and country\n\n**Remember:** No job is "lesser" or "greater" than another. A cleaner, a teacher, and a doctor all contribute to society. What matters is that your work is honest, gives you purpose, and allows you to support yourself and those you love.'),
  q(9, 'Why is it important to know about related careers when planning your future?',
    ['Because related careers offer alternative paths if your first choice does not work out, and they use similar skills', 'Related careers are not important at all', 'You should only focus on one career and ignore everything else', 'Related careers are always less important than the main career'], 0,
    'Knowing about related careers gives you flexibility and more options. If your first career choice does not work out (due to marks, finances, or changing interests), related careers use similar skills and interests.'),
  fb(10, 'NSFAS stands for the National Student Financial ___ Scheme. Work fulfils not only financial needs but also social, emotional, and ___ needs.',
    ['Aid', 'growth'],
    'NSFAS provides financial support (bursaries) to students who cannot afford university or college fees. Work is about more than money — it fulfils our need for social connection, emotional purpose, and personal growth.'),
];

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 11: Personal Diet and Nutrition (Term 4, Weeks 1–2)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch11_lesson1 = [
  t(1, '## Personal Diet and Nutrition\n\nWhat you eat affects how you feel, how you grow, and how well your body and brain work. During puberty, your body needs more nutrition than ever to fuel growth and development.\n\n### Concepts: Personal Diet and Nutrition\n\nA balanced diet gives your body everything it needs to be healthy:\n\n**The food groups:**\n\n| Food group | What it does | Examples |\n|-----------|-------------|----------|\n| **Carbohydrates** | Gives you energy | Bread, rice, mielie meal (pap), potatoes, pasta |\n| **Proteins** | Builds and repairs muscles, bones, and organs | Meat, chicken, fish, eggs, beans, lentils, milk |\n| **Fats** | Stores energy, protects organs, keeps you warm | Oil, butter, avocado, nuts, peanut butter |\n| **Vitamins** | Keeps your body systems working properly | Fruits, vegetables, dairy products |\n| **Minerals** | Builds strong bones, teeth, and blood | Milk (calcium), red meat (iron), bananas (potassium) |\n| **Water** | Keeps body hydrated, transports nutrients | Water, fruit juice (limited), soups |\n| **Fibre** | Helps digestion | Whole grains, vegetables, fruits, beans |\n\n**How much water should a Grade 7 learner drink?**\nAt least 6–8 glasses (about 1.5–2 litres) of water per day. More during hot weather or physical activity.'),
  t(2, '### Factors That Influence Choice of Personal Diet\n\nMany factors affect what people eat:\n\n| Factor | How it influences diet |\n|--------|----------------------|\n| **Ecological (environment)** | What grows in your area — coastal areas have more fish; inland areas have more maize and cattle |\n| **Social factors** | What your family and friends eat, cultural celebrations and feasts, peer pressure to eat junk food |\n| **Economic factors** | How much money your family has — healthy food can be expensive; unhealthy food is often cheaper |\n| **Cultural factors** | Traditional foods, dietary customs, fasting periods, cultural celebrations |\n| **Political factors** | Government food policies, school feeding programmes, food safety regulations |\n\n**South African context:**\n- Many families rely on staple foods like pap, bread, and rice because they are affordable\n- The school feeding programme (National School Nutrition Programme) provides meals to millions of learners\n- Fast food and sugary drinks are major contributors to unhealthy diets\n- South Africa has high rates of both malnutrition (too little food) and obesity (too much unhealthy food)\n\n**Food advertising:**\n- Advertisements often promote unhealthy food (sweets, chips, sugary drinks)\n- Learn to read food labels — check the sugar, salt, and fat content\n- Do not believe everything you see in food advertisements'),
  q(3, 'Why does South Africa have high rates of BOTH malnutrition and obesity?',
    ['Because some families cannot afford enough food (malnutrition) while others eat too much unhealthy food (obesity) — both are forms of poor nutrition', 'Because South Africa has no food at all', 'Because everyone in South Africa eats too much', 'Because malnutrition and obesity are the same thing'], 0,
    'South Africa faces a "double burden" of malnutrition. In poorer communities, families may not get enough nutritious food. At the same time, cheap junk food and sugary drinks contribute to rising obesity rates in all communities.'),
  t(4, '### Ways to Improve Nutritional Value of Own Personal Diet\n\nYou can make healthier food choices even on a limited budget:\n\n**Practical tips for healthy eating:**\n\n| Tip | How to do it |\n|-----|-------------|\n| **Eat more vegetables** | Add spinach, cabbage, carrots, or tomatoes to every meal — they are affordable and nutritious |\n| **Choose whole grains** | Brown bread instead of white, brown rice instead of white |\n| **Drink more water** | Replace sugary drinks with water — it is free and much healthier |\n| **Eat less sugar** | Avoid sweets, chocolates, and sugary drinks |\n| **Eat less salt** | Do not add extra salt to food — too much salt causes high blood pressure |\n| **Eat fruit for snacks** | An apple or banana is healthier and cheaper than chips |\n| **Eat breakfast** | Start the day with pap, bread, or cereal — your brain needs fuel to learn |\n| **Eat beans and lentils** | They are a cheap source of protein if you cannot afford meat |\n\n**A plan for healthy eating habits:**\n1. Eat three balanced meals per day\n2. Drink water instead of fizzy drinks\n3. Eat at least 5 portions of fruits and vegetables per day\n4. Limit sweets, chips, and fast food to occasional treats\n5. Do not skip breakfast — it is the most important meal\n6. Eat together as a family when possible\n7. Be active — combine healthy eating with regular exercise'),
  fb(5, 'A Grade 7 learner should drink at least ___–8 glasses of water per day. The cheapest source of protein for families who cannot afford meat is ___ and lentils.',
    ['6', 'beans'],
    'Adequate hydration requires 6–8 glasses of water daily for young people. Beans and lentils are excellent, affordable sources of protein and are widely available in South Africa.'),
  t(6, '### The Connection Between Diet and Health\n\nWhat you eat has a direct impact on your health:\n\n**Effects of poor nutrition:**\n\n| Poor eating habit | Health consequence |\n|------------------|-------------------|\n| Too little food | Malnutrition, stunted growth, weak immune system |\n| Too much sugar | Tooth decay, diabetes, obesity |\n| Too much salt | High blood pressure, heart disease |\n| Too much fat | Obesity, heart disease, high cholesterol |\n| Skipping breakfast | Poor concentration, tiredness, low marks at school |\n| Too little fruit and vegetables | Vitamin deficiency, weak immune system |\n| Too many fizzy drinks | Weight gain, tooth decay, dehydration |\n\n**Effects of good nutrition:**\n- Strong bones and teeth\n- Healthy body weight\n- More energy for school and sport\n- Better concentration and school performance\n- Stronger immune system (get sick less often)\n- Better mood and emotional well-being\n- Healthy skin, hair, and nails\n\n**The link between nutrition and brain function:**\nYour brain uses about 20% of the energy from the food you eat. If you eat poorly, your brain does not get enough fuel, which affects your ability to concentrate, remember, and learn. Eating breakfast before school is essential for brain performance.'),
  q(7, 'Nosipho often skips breakfast and buys chips and a fizzy drink at the tuck shop for lunch. She complains of tiredness and poor concentration in class. What is the most likely cause?',
    ['Poor nutrition — skipping breakfast and eating junk food does not give her brain and body the fuel they need', 'She is sleeping too much', 'She has a rare medical condition', 'The classroom is too warm'], 0,
    'Skipping breakfast deprives the brain of fuel after a long night without food. Chips and fizzy drinks provide empty calories (sugar and fat) without the nutrients needed for energy and concentration. A healthy breakfast and balanced lunch would improve her energy and focus.'),
  t(8, '### Traditional South African Foods and Nutrition\n\nSouth Africa has a rich tradition of nutritious foods that are often more affordable than processed alternatives:\n\n**Traditional foods and their nutritional value:**\n\n| Food | Nutritional value |\n|------|------------------|\n| **Morogo/imifino** (wild spinach) | Rich in iron, calcium, and vitamins |\n| **Amadumbe** (madumbi) | Good source of carbohydrates and fibre |\n| **Mopane worms** | Extremely high in protein |\n| **Samp and beans (umngqusho)** | Excellent combination of carbohydrates and protein |\n| **Sweet potatoes** | Rich in vitamin A, fibre, and energy |\n| **Sour milk (amasi)** | Rich in protein and probiotics (good bacteria) |\n| **Pumpkin leaves** | High in vitamins A and C, iron |\n\n**Advantages of traditional foods:**\n- Often more nutritious than processed foods\n- Usually cheaper and locally available\n- Environmentally sustainable — they grow naturally in South Africa\n- Part of our cultural heritage\n\n**Combining traditional wisdom with modern nutrition:**\nThe healthiest diet combines traditional South African foods with modern nutrition knowledge. Eat traditional foods like morogo, beans, and amasi while following guidelines about balanced meals, portion sizes, and limiting sugar and salt.'),
  q(9, 'Which traditional South African food is an excellent combination of carbohydrates and protein?',
    ['Samp and beans (umngqusho) — samp provides carbohydrates while beans provide protein', 'Chips and fizzy drinks', 'Sweets and chocolate', 'White bread and margarine'], 0,
    'Samp and beans (umngqusho) is a traditional Xhosa dish that provides a complete nutritional combination. The samp gives carbohydrates for energy, while the beans provide protein for growth and repair.'),
  fb(10, 'Wild spinach, known as ___ or imifino, is rich in iron and vitamins. Your brain uses about ___% of the energy from the food you eat.',
    ['morogo', '20'],
    'Morogo (wild spinach) is a traditional Southern African food that is highly nutritious and often available for free. The brain consumes approximately 20% of your daily energy intake, making good nutrition essential for learning.'),
];

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 12: Common Diseases and Dealing with Grief (Term 4, Weeks 3–4)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch12_lesson1 = [
  t(1, '## Common Diseases and Dealing with Grief\n\nSouth Africa faces many health challenges. Understanding common diseases, how to prevent them, and how to cope when illness leads to loss is essential knowledge for every Grade 7 learner.\n\n### Common Diseases in South Africa\n\n| Disease | What it is | Symptoms |\n|---------|-----------|----------|\n| **Tuberculosis (TB)** | A bacterial infection that mainly affects the lungs | Persistent cough (more than 2 weeks), weight loss, night sweats, coughing up blood |\n| **Diabetes** | A condition where the body cannot properly control blood sugar | Increased thirst, frequent urination, tiredness, blurred vision |\n| **Epilepsy** | A brain condition causing seizures (fits) | Sudden jerking movements, loss of consciousness, confusion |\n| **Obesity** | Being dangerously overweight | Excessive body fat, breathlessness, joint pain, difficulty with physical activity |\n| **Anorexia** | An eating disorder — refusing to eat enough | Extreme thinness, fear of gaining weight, distorted body image |\n| **HIV and AIDS** | A virus that attacks the immune system | Frequent infections, weight loss, tiredness (HIV can have no symptoms for years) |\n| **COVID-19** | A respiratory virus | Fever, cough, loss of taste/smell, difficulty breathing |'),
  t(2, '### Causes of Diseases: Social, Economic, and Environmental Factors\n\nMany diseases are linked to social and environmental conditions:\n\n| Factor | How it causes disease |\n|--------|---------------------|\n| **Alcohol and tobacco** | Smoking causes lung cancer and heart disease; alcohol damages the liver and brain |\n| **Poor eating habits** | High sugar, salt, and fat diets lead to obesity, diabetes, and heart disease |\n| **Physical inactivity** | Lack of exercise contributes to obesity, diabetes, and heart disease |\n| **Poverty** | Poor nutrition, lack of healthcare, overcrowded living conditions |\n| **Lack of clean water** | Waterborne diseases like cholera and diarrhoea |\n| **Overcrowded housing** | TB spreads easily in crowded, poorly ventilated spaces |\n| **Stigma** | People avoid getting tested or treated because they fear discrimination |\n\n**Prevention is key:**\n- Eat a balanced diet and exercise regularly\n- Do not smoke or use alcohol\n- Wash hands frequently\n- Get vaccinated\n- Visit a clinic regularly\n- Know your HIV status — get tested\n- Take medication as prescribed'),
  q(3, 'TB (tuberculosis) spreads more easily in which type of living conditions?',
    ['Crowded, poorly ventilated spaces where many people share a small area', 'Open, well-ventilated areas', 'Clean, spacious homes', 'Outdoor environments'], 0,
    'TB is spread through the air when an infected person coughs or sneezes. Crowded, poorly ventilated living conditions allow the TB bacteria to spread easily between people. This is why TB is common in informal settlements and overcrowded houses.'),
  t(4, '### Treatment Options, Care, and Support\n\nMost common diseases can be managed or treated with proper medical care:\n\n| Disease | Treatment and management |\n|---------|------------------------|\n| **TB** | 6-month course of antibiotics — must complete the FULL course or the TB returns and becomes drug-resistant |\n| **Diabetes** | Healthy diet, exercise, medication (insulin for Type 1), regular check-ups |\n| **Epilepsy** | Anti-seizure medication — taken daily, allows most people to live normal lives |\n| **HIV/AIDS** | ARV (antiretroviral) medication — taken daily, suppresses the virus and allows a long, healthy life |\n| **Obesity** | Balanced diet, regular exercise, reduced sugar and fat intake |\n| **COVID-19** | Rest, fluids, medication for symptoms; vaccination for prevention |\n\n**Resources on health information and health services:**\n- Government clinics and hospitals — free basic healthcare\n- Private doctors and hospitals\n- Community health workers\n- School nurse or health worker\n- National AIDS Helpline: 0800 012 322\n\n**Strategies for living with illness:**\n- Take medication exactly as prescribed\n- Eat a healthy, balanced diet\n- Stay physically active where possible\n- Maintain a positive attitude and strong support network\n- Attend regular check-ups at the clinic\n- Educate yourself about your condition'),
  fb(5, 'A full TB treatment course takes ___ months. ARV stands for ___, which is the medication used to treat HIV.',
    ['6', 'antiretroviral'],
    'TB treatment requires a 6-month course of antibiotics that must be completed in full. ARV (antiretroviral) therapy suppresses the HIV virus and allows people living with HIV to lead long, healthy lives.'),
  t(6, '### Dealing with Grief, Trauma, Loss, and Crises\n\nMany young people in South Africa experience grief and loss — losing a parent, family member, or friend to illness, violence, or other causes.\n\n**What is grief?**\nGrief is the deep sadness you feel when you lose someone or something important to you.\n\n**Common causes of grief for young people:**\n- Death of a parent, grandparent, sibling, or friend\n- Loss of a caregiver to illness (HIV/AIDS, TB, COVID-19)\n- Parents\' divorce or separation\n- Moving to a new school or community\n- Loss of a pet\n\n**Signs of grief:**\n- Sadness, crying, and withdrawal from others\n- Anger, irritability, and outbursts\n- Difficulty concentrating at school\n- Changes in eating and sleeping\n- Physical symptoms (headaches, stomachaches)\n- Loss of interest in things you used to enjoy\n\n**Important:** There is no "right" way to grieve. Everyone experiences grief differently, and there is no set time for how long it takes. What matters is that you do not go through it alone.'),
  q(7, 'After her grandmother passed away, Palesa has been sleeping badly, feeling angry at everyone, and her marks have dropped. Is this normal?',
    ['Yes — changes in sleep, anger, and school performance are all normal responses to grief', 'No — she should have gotten over it by now', 'No — grief only makes you sad, not angry', 'No — real grief does not affect school work'], 0,
    'Grief affects people in many ways — not just sadness. Anger, sleep difficulties, and declining school performance are all normal grief responses. Palesa needs support from trusted adults and possibly a counsellor.'),
  t(8, '### Healthy Ways to Cope with Grief and Loss\n\nHealthy coping helps you work through grief without causing additional harm:\n\n**Healthy coping strategies:**\n- Talk about your feelings with someone you trust\n- Cry when you need to — it is a natural and healthy release\n- Keep a journal or write letters to the person you lost\n- Maintain your daily routine — school, meals, sleep\n- Exercise and stay physically active\n- Spend time with supportive family and friends\n- Remember happy times with the person you lost\n- Join a support group with others who understand\n\n**Unhealthy coping strategies to avoid:**\n- Using alcohol or drugs to numb the pain\n- Isolating yourself from everyone\n- Self-harm (cutting, burning)\n- Pretending everything is fine when it is not\n- Taking anger out on others\n- Skipping school or refusing to eat\n\n**Where to find help:**\n\n| Organisation | Number |\n|-------------|--------|\n| **Childline** | 0800 055 555 |\n| **SADAG** | 0800 567 567 |\n| **Lifeline** | 0861 322 322 |\n\n**Remember:** Asking for help is a sign of strength. Grief is not something you have to face alone — there are people who care and want to help.'),
  q(9, 'Which of the following is an UNHEALTHY way to cope with grief?',
    ['Using alcohol or drugs to numb the pain', 'Talking to a trusted adult about your feelings', 'Exercising and staying active', 'Keeping a journal about your emotions'], 0,
    'Using alcohol or drugs to cope with grief creates additional problems — addiction, health damage, and deeper emotional pain. Healthy coping involves talking, exercising, writing, and seeking support.'),
  fb(10, 'The free SADAG helpline for depression and grief support is ___. Asking for help when you are struggling is a sign of ___, not weakness.',
    ['0800 567 567', 'strength'],
    'SADAG (South African Depression and Anxiety Group) provides free, 24-hour telephonic counselling at 0800 567 567. Seeking help requires courage and is a sign of emotional maturity and strength.'),
];

// ═══════════════════════════════════════════════════════════════════════════════
// CHAPTER 13: Religion and Oral Traditions in South Africa (Term 4, Weeks 5–7)
// ═══════════════════════════════════════════════════════════════════════════════
blockNum = 0;
const ch13_lesson1 = [
  t(1, '## Role of Oral Traditions and Scriptures in Major Religions\n\nSouth Africa is home to people of many different religions. Understanding and respecting different religious traditions is essential for nation-building and living together peacefully.\n\n### What Are Oral Traditions and Scriptures?\n\n**Oral traditions** are stories, teachings, and beliefs passed down through speaking and listening — from grandparents to parents to children — rather than being written down.\n\n**Scriptures** are sacred texts that contain the teachings, history, and laws of a religion.\n\n### Major Religions in South Africa\n\n| Religion | Scripture/Sacred Text | Key beliefs |\n|----------|---------------------|-------------|\n| **Judaism** | Torah (first five books) and Talmud | One God, the covenant between God and the Jewish people, following God\'s laws |\n| **Christianity** | The Bible (Old and New Testaments) | One God in Trinity, salvation through Jesus Christ, love and forgiveness |\n| **Islam** | The Qur\'an | One God (Allah), the Prophet Muhammad as God\'s final messenger, the Five Pillars |\n| **Hinduism** | The Vedas, Bhagavad Gita, Upanishads | Many expressions of one divine reality, karma, dharma, reincarnation |\n| **Buddhism** | Tipitaka (Pali Canon) | The Four Noble Truths, the Eightfold Path, the Middle Way, compassion |\n| **Bahá\'í Faith** | Kitáb-i-Aqdas and writings of Bahá\'u\'lláh | Unity of God, unity of religions, unity of humanity |\n| **African Traditional Religion** | Oral traditions — stories, proverbs, rituals | Ancestors, connection to nature, community, ubuntu |'),
  t(2, '### The Role of Oral Traditions in African Traditional Religion\n\nAfrican Traditional Religion is one of the oldest religious traditions in South Africa. It relies heavily on oral tradition rather than written scripture.\n\n**How oral traditions are used:**\n- Elders pass down stories, proverbs, and teachings to younger generations\n- Rituals, ceremonies, and celebrations preserve cultural and spiritual knowledge\n- Proverbs contain moral lessons (e.g., "Umuntu ngumuntu ngabantu" — a person is a person through other persons)\n- Storytelling teaches values, history, and appropriate behaviour\n- Songs and praise poetry celebrate ancestors and express spiritual beliefs\n\n**Key beliefs in African Traditional Religion:**\n- **Ancestors** play an important role in guiding and protecting the living\n- There is a deep connection between humans, nature, and the spiritual world\n- **Ubuntu** — the belief that we are all interconnected and responsible for each other\n- Community is more important than the individual\n- Respect for elders and traditional leaders\n\n**African Traditional Religion and the Constitution:**\nThe South African Constitution (Section 15) protects the right to practise African Traditional Religion just as it protects all other religions. No religion is "better" or more valid than another.'),
  q(3, 'How are religious and moral teachings passed down in African Traditional Religion?',
    ['Through oral traditions — stories, proverbs, songs, and rituals passed from elders to younger generations', 'Through a single written holy book', 'Through television and social media', 'Through formal classroom education only'], 0,
    'African Traditional Religion relies on oral tradition — the spoken word passed from generation to generation. Elders share stories, proverbs, songs, and ceremonies to teach values, history, and spiritual beliefs.'),
  t(4, '### Scriptures in Major World Religions\n\n**The Torah (Judaism):**\n- The first five books of the Hebrew Bible\n- Contains God\'s laws, including the Ten Commandments\n- Read aloud in synagogues every Sabbath\n- Teaches justice, compassion, and obedience to God\n\n**The Bible (Christianity):**\n- Consists of the Old Testament and New Testament\n- The New Testament tells of Jesus Christ\'s life, teachings, death, and resurrection\n- Teaches love, forgiveness, and service to others\n- The most widely distributed book in South Africa\n\n**The Qur\'an (Islam):**\n- Believed to be the word of God (Allah) revealed to the Prophet Muhammad\n- Written in Arabic and often memorised completely (those who do are called Hafiz)\n- Teaches submission to God, prayer, charity, and moral living\n- The Five Pillars guide Muslim life: faith declaration, prayer, fasting, charity, pilgrimage\n\n**The Vedas and Bhagavad Gita (Hinduism):**\n- Among the oldest religious texts in the world\n- The Bhagavad Gita teaches about duty, righteousness, and the nature of reality\n- Hindus believe in karma (your actions determine your future), dharma (duty), and reincarnation (rebirth)'),
  fb(5, 'The sacred text of Islam is called the ___. The Torah contains the first ___ books of the Hebrew Bible.',
    ['Qur\'an', 'five'],
    'The Qur\'an is the holy book of Islam, believed to be the word of Allah revealed to the Prophet Muhammad. The Torah consists of the first five books of the Hebrew Bible and is central to Jewish faith and practice.'),
  t(6, '### Buddhism and the Bahá\'í Faith\n\n**The Tipitaka (Buddhism):**\n- The Buddhist scriptures, also called the Pali Canon\n- Contains the teachings of Siddhartha Gautama, the Buddha ("the Awakened One")\n- Teaches the Four Noble Truths:\n  1. Life involves suffering\n  2. Suffering is caused by desire and attachment\n  3. Suffering can end\n  4. The way to end suffering is the Noble Eightfold Path\n- The Eightfold Path includes right understanding, right intention, right speech, right action, right livelihood, right effort, right mindfulness, and right concentration\n- Emphasises compassion, meditation, and the Middle Way (avoiding extremes)\n\n**The Bahá\'í Writings:**\n- Founded by Bahá\'u\'lláh in the 19th century\n- The Kitáb-i-Aqdas is the central book of Bahá\'í laws and teachings\n- Key beliefs:\n  - There is one God who has revealed truth through many religions\n  - All religions share the same fundamental truth\n  - All of humanity is one family\n  - Equality of men and women\n  - Elimination of prejudice\n  - Universal education\n- The Bahá\'í Faith emphasises unity, peace, and service to humanity'),
  q(7, 'Which religion teaches that all the world\'s major religions share the same fundamental truth and come from one God?',
    ['The Bahá\'í Faith — it teaches the unity of God, the unity of religion, and the unity of humanity', 'Buddhism — which focuses on ending suffering', 'African Traditional Religion — which focuses on ancestors', 'Only Christianity makes this claim'], 0,
    'The Bahá\'í Faith uniquely teaches that all major religions are stages in one continuous process of divine revelation. It holds that the founders of all major religions (Moses, Jesus, Muhammad, Buddha, etc.) brought teachings from the same God.'),
  t(8, '### Respecting Religious Diversity in South Africa\n\nSouth Africa\'s Constitution protects religious freedom. Living together peacefully means respecting all religions:\n\n**Section 15 of the Constitution:**\n- Everyone has the right to freedom of conscience, religion, thought, belief, and opinion\n- No one may be forced to follow a particular religion\n- Religious observances may be conducted at public schools provided they are voluntary and equitable\n\n**How to show respect for different religions:**\n- Learn about religions different from your own\n- Do not mock or make fun of anyone\'s beliefs, practices, or sacred objects\n- Respect dietary requirements (halaal food for Muslims, kosher food for Jews, vegetarianism for some Hindus)\n- Be sensitive during religious holidays and fasting periods\n- Ask respectful questions rather than making assumptions\n\n**What all major religions share:**\nDespite their differences, all major religions teach:\n- Treat others with kindness and compassion\n- Help the poor and vulnerable\n- Live honestly and with integrity\n- Respect the dignity of every human being\n- Seek peace and avoid violence\n\n**Social development by religious organisations:**\nReligious organisations make important contributions to South African society through feeding schemes, orphanages, schools, clinics, shelters, and disaster relief (for example, Gift of the Givers, the Salvation Army, Hindu temple feeding programmes, and mosque-based charity).'),
  q(9, 'Which section of the South African Constitution protects freedom of religion?',
    ['Section 15 — everyone has the right to freedom of conscience, religion, thought, belief, and opinion', 'Section 9 — the right to equality', 'Section 24 — the right to a healthy environment', 'Section 29 — the right to education'], 0,
    'Section 15 of the Constitution specifically protects religious freedom. It ensures that everyone in South Africa is free to practise their religion without interference, and that no person may be forced to follow a particular faith.'),
  fb(10, 'Section ___ of the Constitution protects freedom of religion. Despite their differences, all major religions teach people to treat others with kindness and ___.',
    ['15', 'compassion'],
    'Section 15 protects the right to freedom of religion, conscience, thought, belief, and opinion. Compassion — caring about others\' suffering and wanting to help — is a universal value shared by all major religions.'),
];

